/* DAWAH X — ahmad, অধ্যায় 27 · খণ্ড 27 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][27]=[[5201,5201,"","আমরা দুটো উপায় নিয়ে কথা বলেছি, যার মাধ্যমে আমরা আপনার টাকা নিয়ে এসেছি, যে একটি ছেলে ভুলে গেছে যে ঈশ্বরকে ছেড়ে দিয়েছে। তরুণীদের হত্যা।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي بَعْضِ مَغَازِيهِ امْرَأَةً مَقْتُولَةً فَأَنْكَرَ ذَلِكَ ‏ ‏وَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5202,5202,"","আমরা দুটো উপায় নিয়ে কথা বলেছি একটা ছেলের জন্য যে এটা করতে ভুলে গেছে, সে সম্ভবত আমাকে হুমকি দিচ্ছে আর সে আমাকে হুমকি দিচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏","","",""],[5203,5203,"","আমরা একটা দাসের সাথে কথা বলেছি যে এটা নয়, আমাদের এমন একটা ছেলের কথা জিজ্ঞেস করতে হবে যে পাশ হয়ে গেছে আর আমরা তার বাটন নিয়ে পাগল হয়ে গেছি। লুকিয়ে থেকে তিনি বলেছিলেন তিনি কখনো ঈশ্বরের দিকে তাকিয়ে তা করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏يَقُولُ ‏ ‏أَمَرْتُ ‏ ‏مُسْلِمَ بْنَ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏نَافِعِ بْنِ عَبْدِ الْحَارِثِ ‏ ‏أَنْ يَسْأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَنَا جَالِسٌ بَيْنَهُمَا مَا سَمِعْتَ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَنْ جَرَّ إِزَارَهُ مِنْ الْخُيَلَاءِ شَيْئًا فَقَالَ سَمِعْتُهُ يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5204,5204,"","তিনি ঈশ্বরের কাছে প্রার্থনা করতে যাচ্ছিলেন, তিনি সেখানে উপস্থিত হয়ে গর্ভ ও বিখ্যাতদের মধ্যে পৌঁছাতে পারবেন","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَمْزَةَ يَعْنِي السُّكَّرِيَّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ يَعْنِي الصَّائِغَ ‏ ‏عَنِ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْصِلُ بَيْنَ ‏ ‏الْوَتْرِ ‏ ‏وَالشَّفْعِ ‏ ‏بِتَسْلِيمَةٍ وَيُسْمِعُنَاهَا ‏","","",""],[5205,5205,"","আমরা বাবার জিনিয়াসের কথা বলেছি যে একটা ছেলের অভিশাপ সৃষ্টি করেছে, ঈশ্বর তাকে তার কাছে সমর্পণ করতে বলেছেন যে, সে যদি বিজয় না করার চেষ্টা করে, তাহলে তুমি স্বপ্ন দেখছো।","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ حَالِفًا فَلَا يَحْلِفْ إِلَّا بِاللَّهِ عَزَّ وَجَلَّ وَكَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَحْلِفُ بِآبَائِهَا فَقَالَ لَا تَحْلِفُوا بِآبَائِكُمْ ‏","","",""],[5206,5206,"","আমরা একটা ভালো মেয়ের কথা বলেছি যে তাকে একজন মায়ের ছেলের কথা বলেছিল, তোমার টাকার লোকেরা তার মৃত্যুর ভয়ে গান গেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَخْبَرَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ امْرَأَةً كَانَتْ ‏ ‏تَرْعَى عَلَى آلِ ‏ ‏كَعْبِ بْنِ مَالِكٍ ‏ ‏غَنَمًا ‏ ‏بِسَلْعٍ ‏ ‏فَخَافَتْ عَلَى شَاةٍ مِنْهَا الْمَوْتَ فَذَبَحَتْهَا بِحَجَرٍ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5207,5207,"","আমরা একটি হারুনন সম্পর্কে কথা বলেছি যে আমরা এমন এক মানুষের কাছ থেকে কিছু লাভ করেছি, যে কিনা কিনা আত্মসমর্পন থেকে একজন মানুষের কথা শুনেছে। তিনি ভয় পেয়ে গিয়েছিলেন যে, তিনি পাথরের ভয়ে তার সঙ্গে পালিয়ে যান এবং প্রভুর কাছে তা করতে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فِي الْمَسْجِدِ أَنَّ ‏ ‏جَارِيَةً ‏ ‏لِكَعْبِ بْنِ مَالِكٍ ‏ ‏كَانَتْ ‏ ‏تَرْعَى غَنَمًا لَهُ ‏ ‏بِسَلْعٍ ‏ ‏فَعَرَضَ لِشَاةٍ مِنْهَا فَخَافَتْ عَلَيْهَا فَأَخَذَتْ ‏ ‏لِخَافَةً ‏ ‏مِنْ حَجَرٍ فَذَبَحَتْهَا بِهَا فَسَأَلُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5208,5208,"","আমরা হারুনের থেকে ভাল কথা বলেছি, সে আমাদের শত্রুকে কথা দিতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ يُسَافَرَ بِالْمُصْحَفِ إِلَى أَرْضِ الْعَدُوِّ ‏","","",""],[5209,5209,"","আমরা ঈশ্বর কে সর্বোচ্চ করার জন্য বলেছি, আর তারপর আমি আপনার সম্পর্কে অজ্ঞাত ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏يَنْهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏ ‏وَذَاكَ أَنَّ أَهْلَ الْجَاهِلِيَّةِ كَانُوا يَبِيعُونَ ذَلِكَ الْبَيْعَ فَنَهَاهُمْ عَنْ ذَلِكَ ‏","","",""],[5210,5210,"","আমরা একটা ছেলের ব্যাপারে কথা বলেছি যে ভাববাদীর কথা শুনেছেন... ...তুমি তাকে ছেড়ে দাও... ...যখন আমি বিভ্রান্ত হয়ে গেছি আর তার টাকা দিয়ে গেছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَرَكَ الْعَصْرَ مُتَعَمِّدًا حَتَّى تَغْرُبَ الشَّمْسُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[5211,5211,"","আমরা আমার বাবা আর মেয়ের সাথে কথা বলেছি যে ঈশ্বর তোমাদের আশীর্বাদ করেছেন। তারা তোমাকে একজন ভাল মানুষ হত্যা করা থেকে বিরত রাখতে পারেনি। যে আমাকে বলেছে ঈশ্বর তার নিজের শান্তিয় পাঠাতে আর সে যা বলে তাই করবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا نِسَاءَكُمْ الْمَسَاجِدَ وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏ابْنٌ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏بَلَى وَاللَّهِ لَنَمْنَعُهُنَّ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏تَسْمَعُنِي أُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ مَا تَقُولُ ‏","","",""],[5212,5212,"","আমরা বলেছিলাম কিভাবে ঈশ্বর একটা বাচ্চা ছিলেন। সে এটা করতে গিয়ে সে সূর্য দেখার পর সে গান পৌঁছে দেবে। আমি প্রভু আর মাস্টারদেরও দিয়ে দিলাম। আমার মা একটা হাত দিয়ে আমার বাবাকে বড় অঙ্কের টাকা দিয়ে বড় করে তুলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ عُمَرُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَدْرُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مَرْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَائِشَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ غَدَاةٍ بَعْدَ طُلُوعِ الشَّمْسِ فَقَالَ ‏ ‏رَأَيْتُ قُبَيْلَ الْفَجْرِ كَأَنِّي أُعْطِيتُ الْمَقَالِيدَ وَالْمَوَازِينَ فَأَمَّا الْمَقَالِيدُ فَهَذِهِ الْمَفَاتِيحُ وَأَمَّا الْمَوَازِينُ فَهِيَ الَّتِي تَزِنُونَ بِهَا فَوُضِعْتُ فِي كِفَّةٍ وَوُضِعَتْ أُمَّتِي فِي كِفَّةٍ فَوُزِنْتُ بِهِمْ فَرَجَحْتُ ثُمَّ جِيءَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏فَوُزِنَ بِهِمْ فَوَزَنَ ثُمَّ جِيءَ ‏ ‏بِعُمَرَ ‏ ‏فَوُزِنَ فَوَزَنَ ثُمَّ جِيءَ ‏ ‏بِعُثْمَانَ ‏ ‏فَوُزِنَ بِهِمْ ثُمَّ رُفِعَتْ ‏","","",""],[5213,5213,"","আমরা একজন বড় ছেলের জন্য শহরের সেরাটা নিয়ে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর একজন মানুষ তার কাছে প্রার্থনা করেছে হারকিউসি থেকে আত্মসমর্পণ করবে আর আমরা ঈশ্বরের সন্তান হব, তাই তুমি বলেছিলে, তুমি বলো, সকালে ধোঁকা দিয়ে কাল বাকি আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَنْبَأَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏وَأَنَا بَيْنَهُ وَبَيْنَ ‏ ‏الْبَدَوِيِّ فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ صَلَاةُ اللَّيْلِ فَقَالَ ‏ ‏مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَوَاحِدَةً وَرَكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏","","",""],[5214,5214,"","আমরা একটা ছেলের কথা বলেছি যে আমার বাবাকে ভালোবাসে ঈশ্বরের পুত্রের জন্য, সে বলবে যে তুমি মেয়েদের আমার বাবাকে খুঁজে বের করতে পারবে না আর আমি তাদের ভয় পাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْعَوَّامِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ أَنْ يَخْرُجْنَ إِلَى الْمَسَاجِدِ ‏ ‏وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ ‏","","",""],[5215,5215,"","আমরা একটি বালতি দিয়ে একটি সুখী ছেলে সম্পর্কে কথা বলেছি। \"আর নয়\" বলে আমরা তাকে বললাম যে, একটি ছেলের জন্য কাজ করেছে। দয়া করে, ওরা শার্ট পরেনি, আর আমরা বেঁচে থাকতে পারবো না। দুঃখ তাদেরকে দু'টি থেকে বের করে দ্বিতীয় সেকেন্ডের মধ্যে কোন কিছু পর পর পর পর পর পর পর না। দ্বিতীয় শাস্তি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نَافِعٍ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً ‏ ‏إِنَّ ‏ ‏عُمَرَ بْنَ نَافِعٍ ‏ ‏أَخْبَرَهُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَلْبَسُ إِذَا أَحْرَمْنَا قَالَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخِفَافَ إِلَّا أَنْ يَكُونَ رَجُلٌ لَيْسَتْ لَهُ نَعْلَانِ فَيَلْبَسَ الْخُفَّيْنِ وَيَجْعَلَهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا تَلْبَسُوا شَيْئًا مِنْ الثِّيَابِ مَسَّهُ ‏ ‏الزَّعْفَرَانُ ‏ ‏وَلَا ‏ ‏الْوَرْسُ ‏","","",""],[5216,5216,"","আমরা তার ছেলেকে পার্থক্য করার জন্য তাকে সাহায্য করতে চাই, অক্সিজেন বিক্রি করতে হবে না যতক্ষণ না তার ফ্যাকাশে হয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبَايَعُوا الثَّمَرَ حَتَّى يَبْدُوَ صَلَاحُهُ ‏","","",""],[5217,5217,"","তিনি বলেন যে আমার বাবা আমাদের বলেছেন যে আমরা তাকে একটা ছেলের কাছে বিক্রি করতে বলেছিলাম যে ঈশ্বরকে এটা দিতে হবে আর এটা রাখার সব ক্ষমতা দিয়ে দিতে হবে। বের হও।","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَخْبَرَنَا ‏ ‏يَعْنِي ‏ ‏يَزِيدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي إِنْسَانٍ ‏ ‏أَوْ مَمْلُوكٍ ‏ ‏كُلِّفَ عِتْقَ بَقِيَّتِهِ فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ يُعْتِقُهُ بِهِ فَقَدْ جَازَ مَا عَتَقَ ‏","","",""],[5218,5218,"","আমরা আমাদের সংবাদ নিয়ে অনেক কথা বলেছি, সে যা শুনেছে তা জেনে খুশি। ঈশ্বর তাকে জানেন আর সে তাকে তোমার বাবার কাছে বলবে, তোমার ভাই নয়, তোমার ভাই। আপনার ছেলে আপনার কথা ও ঈশ্বরের কাছে আপনার কথা বলতে চেয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ عَنْ الَّذِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي بِهِ يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏وَذَكَرَ ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَزِيدُ هَؤُلَاءِ الْكَلِمَاتِ مِنْ عِنْدِهِ لَبَّيْكَ ‏ ‏وَالرَّغْبَاءُ ‏ ‏إِلَيْكَ وَالْعَمَلُ لَبَّيْكَ لَبَّيْكَ ‏","","",""],[5219,5219,"","আমরা কথা বলেছি কিভাবে আমরা তাকে ভালো কিছু করতে পেরেছি যে সে একটা ছেলেকে নিজের উদ্দেশ্যে ঈশ্বরের কাছে পাঠানো হয়েছে বলে। সে কোন অপরাধ করেনি যারা তাদের হত্যা করেছে, নির্বোধ আর একাকী হৃদয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏فِي قَتْلِ مَنْ قَتَلَ مِنْهُنَّ الْغُرَابُ وَالْفَأْرَةُ وَالْحِدَأَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْعَقْرَبُ ‏","","",""],[5220,5220,"","আমরা একটা ছেলের কথা বলেছি যে রাতে একটা ছেলে আছে। আমি গান করার আগে তাকে তার রাস্তা দিয়ে দিয়ে দেবো। তারা হয়তো তার জন্য প্রার্থনা করেছিল এবং বললো, ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন। ভাল্লুকের জন্য শেষ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ حَوْلَهُ فَأَسْرَعْتُ لِأَسْمَعَ كَلَامَهُ فَتَفَرَّقَ النَّاسُ قَبْلَ أَنْ أَبْلُغَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً قَبْلَ أَنْ أَنْتَهِيَ إِلَيْهِمْ ‏ ‏فَسَأَلْتُ ‏ ‏رَجُلًا ‏ ‏مِنْهُمْ مَاذَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5221,5221,"","আমরা তাকে এমন কিছু করার জন্য বলতে বলেছিলাম, যা তিনি আমাদের বলেছিলেন । আমি তাকে বলেছি যে সে আমাকে দেখেছে, দ্রুত কিছু কথা বলে, যা বলবে, তা নিয়ে তাড়াতাড়ি এসো। সে বলত আমরা রাতের গডফাদারকে চুরি করে ফেলব.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ أَخْبَرَهُ قَالَ ‏ ‏أَقْبَلْنَا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏وَنَحْنُ نَسِيرُ مَعَهُ وَمَعَهُ ‏ ‏حَفْصُ بْنُ عَاصِمِ بْنِ عُمَرَ ‏ ‏وَمُسَاحِقُ بْنُ عَمْرِو بْنِ خِدَاشٍ ‏ ‏فَغَابَتْ لَنَا الشَّمْسُ فَقَالَ أَحَدُهُمَا الصَّلَاةَ فَلَمْ يُكَلِّمْهُ ثُمَّ قَالَ لَهُ الْآخَرُ الصَّلَاةَ فَلَمْ يُكَلِّمْهُ فَقَالَ ‏ ‏نَافِعٌ ‏ ‏فَقُلْتُ لَهُ الصَّلَاةَ فَقَالَ إِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏عَجِلَ ‏ ‏بِهِ السَّيْرُ جَمَعَ مَا بَيْنَ هَاتَيْنِ الصَّلَاتَيْنِ فَأَنَا أُرِيدُ أَنْ أَجْمَعَ بَيْنَهُمَا قَالَ فَسِرْنَا أَمْيَالًا ثُمَّ نَزَلَ فَصَلَّى ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَحَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏هَذَا الْحَدِيثَ مَرَّةً أُخْرَى فَقَالَ سِرْنَا إِلَى قَرِيبٍ مِنْ رُبُعِ اللَّيْلِ ثُمَّ نَزَلَ فَصَلَّى ‏","","",""],[5222,5222,"","আমরা আমাদের কথোপকথন সম্পর্কে কথা বলেছি এবং এটা ঘটেছে যখন আমাকে মুক্ত হতে বলা হয়েছিল, আমার কুকুরের চার্জ করা হয়েছে, যখন সে ঈশ্বরের কাছে প্রার্থনা করেছিল, তখন সে ঈশ্বরের কাছে আত্মসমর্পণ করবে। ঈশ্বর আদেশ দিয়েছেন, বানরগুলো মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ حَارِثَةَ الْكَلْبِيِّ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ مَا كُنَّا نَدْعُوهُ إِلَّا ‏ ‏زَيْدَ بْنَ مُحَمَّدٍ ‏ ‏حَتَّى نَزَلَ الْقُرْآنُ ‏ { ‏ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ ‏}","","",""],[5223,5223,"","আমরা আমাদের কথোপকথনের কথা বলেছিলাম, আর এটা আমার ছেলে এর মাধ্যমে এসেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার হাঁটুর র‍্যালির পর আত্মসমর্পণের জন্য আহবান নিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ ‏","","",""],[5224,5224,"","আমরা কথা বলেছিলাম, কিভাবে ঈশ্বর শুনেছেন যে আমি যা বলি তা না করতে, আমি শুরু করি না হয় আমি এটা করতে যাচ্ছি, অথবা সিংহাসনের ছেলে, যার মধ্যে কোনদিন শত্রু ছিল। সে ডিনার করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ مَا نَعْمَلُ فِيهِ أَمْرٌ مُبْتَدَعٌ أَوْ مُبْتَدَأٌ أَوْ أَمْرٌ قَدْ فُرِغَ مِنْهُ قَالَ ‏ ‏أَمْرٌ قَدْ فُرِغَ مِنْهُ فَاعْمَلْ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ كُلًّا مُيَسَّرٌ فَأَمَّا مَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ فَإِنَّهُ يَعْمَلُ لِلسَّعَادَةِ وَمَنْ كَانَ مِنْ أَهْلِ الشَّقَاءِ فَإِنَّهُ يَعْمَلُ لِلشَّقَاءِ ‏","","",""],[5225,5225,"","আমরা একটা আবেগের ছেলে কথা বলেছি যা আমরা পাপ সন্তানের জন্য বিচার করার ব্যাপারে কথা বলেছি, ঈশ্বর আছে আর যদি আমি জনতার সাথে যোগ দেওয়ার কথা বলি সে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[5226,5226,"","আমরা এক ধরনের আবেগ দ্বারা বাপ্তাইজিত হয়েছি... ...আমি একটা রীতির কথা শুনেছি... ...যা আমি শুনেছি... ...তারা বলতে চায়, রাতের প্রার্থনা আমার মত... ...যদি সে সকালে তোমার দিকে ঘুরে যায়। সে যা বলেছে তা হল তুমি প্রতি দুই রাস্তায় ছেড়ে দিচ্ছ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا رَأَيْتَ أَنَّ الصُّبْحَ يُدْرِكُكَ ‏ ‏فَأَوْتِرْ ‏ ‏بِوَاحِدَةٍ قَالَ فَقِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا مَثْنَى مَثْنَى قَالَ تُسَلِّمُ فِي كُلِّ رَكْعَتَيْنِ ‏","","",""],[5227,5227,"","আমরা একটি দৈত্যের শাস্তির কথা বলেছি যা আমি শুনেছি একটি দৈত্যের সন্তান, আমি চেষ্টা করে তিন বার কথা বলব.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏ ‏وَطَبَّقَ ‏ ‏شُعْبَةُ ‏ ‏يَدَيْهِ ثَلَاثَ مَرَّاتٍ وَكَسَرَ الْإِبْهَامَ فِي الثَّالِثَةِ ‏ ‏قَالَ ‏ ‏عُقْبَةُ ‏ ‏وَأَحْسِبُهُ قَالَ وَالشَّهْرُ ثَلَاثُونَ وَطَبَّقَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[5228,5228,"","আমরা একটি যুদ্ধের শাস্তি হিসেবে একটি দেবতা পুত্রকে শাস্তি হিসেবে নিয়ে এসেছি যে আবেগ-উৎসরিত কথা বলেছি, আল্লাহ তাকে দশম বা অন্যটি দিয়ে গোসল করাতে হবে। তোমার জীবন, বেঁচে থাকা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏ ‏يَعْنِي لَيْلَةَ الْقَدْرِ ‏ ‏فَإِنْ ضَعُفَ أَحَدُكُمْ أَوْ عَجَزَ فَلَا يُغْلَبَنَّ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[5229,5229,"","আমরা আবেগ নিয়ে প্রার্থনা করছি আমরা একটা আবিষ্কার করেছি যে, এমন এক ছেলে যে এটা করেছে তার কাছে আমি বড় হয়েছি, সে এমন একজন ছেলে যে বড় হয়েছে, সে তার জন্য প্রার্থনা করছে, আর সে আত্মসমর্পণ করবে সে এটা তার কাছ থেকে শুনেছি যে তারা তোমার নাম পালন করেছে আর সে মারা যেতে পারত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏أَهَلْ نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ زَعَمُوا ذَلِكَ فَقُلْتُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى فَقَالَ قَدْ زَعَمُوا ذَلِكَ فَقُلْتُ أَنْتَ سَمِعْتَهُ مِنْهُ فَقَالَ قَدْ زَعَمُوا ذَلِكَ فَصَرَفَهُ اللَّهُ عَنِّي وَكَانَ إِذَا قِيلَ لِأَحَدٍ أَنْتَ سَمِعْتَهُ غَضِبَ وَهَمَّ يُخَاصِمُهُ ‏","","",""],[5230,5230,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...ঈশ্বরের পুত্র তার দুঃখের কারনে... ...আমি যা বলতে চাচ্ছি তা নিয়ে...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ يَعْنِي السَّخْتِيَانِيَّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِرَبِّهَا الْأَوَّلِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[5231,5231,"","আমরা আবেগ নিয়ে কথা বলেছি যার মূল্য কত তা নিয়ে আমরা কঠিন সমস্যার সম্মুখীন হয়েছি। তারপর তোমাদের সবাইকে একত্র করে জিজ্ঞেস করবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَاحَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[5232,5232,"","আমরা আবেগে বাপ্তাইজিত হয়েছি, আমরা একটা সমস্যা নিয়ে এসেছি এটা ভুলে যে তিনি একটা ছেলে যে তালাকপ্রাপ্ত হয়েছে, যখন ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং তাকে হত্যা করতে বলা হত আমি ওর মুখ থেকে এই তালাকের কথা বের করার চেষ্টা করছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏طَلَّقْتُ امْرَأَتِي وَهِيَ حَائِضٌ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ ‏ ‏مُرْهُ فَلْيُرَاجِعْهَا ثُمَّ إِذَا طَهُرَتْ فَلْيُطَلِّقْهَا ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَحَسِبَ تِلْكَ التَّطْلِيقَةَ قَالَ ‏ ‏فَمَهْ ‏","","",""],[5233,5233,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের ভুলে যাওয়ার আনন্দ বহন করতে যে আমি একটি ছেলেকে ক্ষমা করতে বলবো। সকালে আমার ছেলে তার কাছে প্রার্থনা করছিল এবং সে তার কাছে প্রার্থনা করেছিল। আমি যা বলবো, তা যখন বলবো, আমি বলবো আমি লবিতে যা পড়ি, আমি বলবো এটা খুব খারাপ। আমি শপথ করছি, ঘটনাগুলো ঈশ্বরের কাছে আছে। তিনি তাকে আদেশ দিয়েছিলেন এবং আমাকে পুনরায় ফোন করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏مَا أَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ مَثْنَى مَثْنَى وَيُوتِرُ بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ قَالَ ‏ ‏أَنَسٌ ‏ ‏قُلْتُ فَإِنَّمَا أَسْأَلُكَ مَا أَقْرَأُ فِي الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ فَقَالَ بَهْ بَهْ إِنَّكَ ‏ ‏لَضَخْمٌ ‏ ‏إِنَّمَا أُحَدِّثُ ‏ ‏أَوْ قَالَ إِنَّمَا أَقْتَصُّ لَكَ الْحَدِيثَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏بِرَكْعَةٍ مِنْ آخِرِ اللَّيْلِ ثُمَّ يَقُومُ كَأَنَّ الْأَذَانَ أَوْ الْإِقَامَةَ فِي أُذُنَيْهِ ‏","","",""],[5234,5234,"","আমরা একটি শিয়ালের মাধ্যমে একত্রিত হয়েছি, যার মাধ্যমে আমি ঈশ্বরের কাছে এক সুখী হাত পেয়েছি, যা একটি ছেলে হবার জন্য হয়। ঈশ্বর আদেশ দিয়েছেন, তিনি আত্মসমর্পণ করবেন এবং তিনি আত্মসমর্পণ করবেন তার টাকাপয়সাই হয়তো প্রথম যে - উপায়ে তার কথা শেষ হয়ে যায়, তা ভেঙে ফেলার জন্য তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন । সে আত্মসমর্পণ করেছে আর তারপর সে যখন বলেছিল সে ঈশ্বরের কথা বলেছে, তখন তার কাছে প্রার্থনা করল এবং জিজ্ঞেস করলো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ رَبِّهِ بْنَ سَعِيدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ بَاعَ نَخْلًا قَدْ أُبِّرَتْ فَثَمَرَتُهَا لِلْأَوَّلِ وَأَيُّمَا رَجُلٍ بَاعَ مَمْلُوكًا وَلَهُ مَالٌ فَمَالُهُ لِرَبِّهِ الْأَوَّلِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَحَدَّثْتُهُ ‏ ‏بِحَدِيثِ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّهُ حَدَّثَ بِالنَّخْلِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَمْلُوكِ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏عَبْدُ رَبِّهِ ‏ ‏لَا أَعْلَمُهُمَا جَمِيعًا إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ مَرَّةً أُخْرَى فَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَشُكَّ ‏","","",""],[5235,5235,"","আমরা একটি দাঙ্গার কথা শুনেছি, যে কিনা এই অভিযান শুনতে পেয়েছে, ঈশ্বরের তাকে উদ্ধার করতে হবে এবং জীবনের গৌরব প্রদান করতে হবে। ''আর গাঁথনিতে ফুৎকারিণীদের ব্যতীত --","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏صَدَقَةَ بْنَ يَسَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّأْمِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏ذَاتَ عِرْقٍ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[5236,5236,"","আমরা আবেগ নিয়ে কথা বলেছি, যা ছেলে ও ছেলের ব্যাপারে ভালো বিজ্ঞান সৃষ্টি করেছে। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি আত্মসমর্পণ করেছেন যে তিনি নিজেকে সফল হতে পারেন না তার পিপাসার সঙ্গে এমনভাবে কাজ করে যেন সে তার কাছে তার কাছে তার কাছে ফিরে আসে, যেন তার কাছে তার কাছে তার কাছে তার কাছে তার কাছে তার কাছে তার কাছে ফিরে আসে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لِرَجُلٍ أَنْ يُعْطِيَ الْعَطِيَّةَ ثُمَّ يَرْجِعَ فِيهَا إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ وَمَثَلُ الَّذِي يُعْطِي الْعَطِيَّةَ ثُمَّ يَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ ثُمَّ عَادَ فِيهِ ‏","","",""],[5237,5237,"","আমরা ঈশ্বরের সুখী পুত্রকে শুনতে আবেগী প্রচেষ্টার কথা বলেছি, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং ডাক্তার আর গর্ভের শোক আর হত্যা এর জন্য আত্মসমর্পণ করবেন। দুঃখের দুঃখের কথা বলতে গিয়ে দুঃখ কষ্টকে কষ্ট দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْخَالِقِ ‏ ‏سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏وَقَدْ ذُكِرَ ‏ ‏الْمُزَفَّتُ ‏ ‏عَنْ غَيْرِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[5238,5238,"","আমরা একটা প্রথার কথা বলেছি... ...আমি বাবার জাদু শুনেছি তার কথা শুনে। সে বলল, আমি একটা ছেলের সাথে প্রার্থনা করেছি যার একটা ছেলের সাথে ছিল। একটু দূরে চলে গেল আর তারপর দু'জন নিষ্ঠুরতার জন্য প্রার্থনা করবে। মনে করো, যা বললে, ঈশ্বরকে দেখে তোমার টাকা পাওয়াটা সার্থক হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ مَالِكٍ الْهَمْدَانِيَّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏بِجَمْعٍ ‏ ‏فَأَقَامَ فَصَلَّى الْمَغْرِبَ ثَلَاثًا ثُمَّ صَلَّى الْعِشَاءَ رَكْعَتَيْنِ بِإِقَامَةٍ وَاحِدَةٍ ‏ ‏قَالَ فَسَأَلَهُ ‏ ‏خَالِدُ بْنُ مَالِكٍ ‏ ‏عَنْ ذَلِكَ فَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ مِثْلَ هَذَا فِي هَذَا الْمَكَانِ ‏","","",""],[5239,5239,"","আমরা এক প্রবল আবেগে বাপ্তাইজিত হয়েছি, আমরা একসাথে আগুনের শিখা এনেছি... ...আমাদের সামনে একটা কুঁড়েঘরের উপর... ...যে আমি শুনেছি ঈশ্বরের পুত্র, ঈশ্বরের কাছে প্রার্থনা করে। আনুগত্য গড়ে তোলার এবং তাঁর দানের অর্থ কী?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏","","",""],[5240,5240,"","আমরা একটি আবেগ দ্বারা বাপ্তাইজিত হয়েছি আমরা প্রভুর পুত্র একটি পুত্র সন্তানের নামে একটি পুত্র নিহত একটি পুত্র হত্যা করা হবে একটি পুত্র একটি পুত্র সন্তান হবে হবে হবে হবে হবে একটি পুত্র একটি পুত্র সন্তান হবে হবে হবে ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং রাতের বেলা আমাকে পাগলের কাছে আত্মসমর্পণ করবেন, তারপর আমি তাকে আত্মসমর্পণ করবো। খুন করে তারপর খুন করে হত্যা করতে বলা হয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ فَمَا أَصْنَعُ قَالَ ‏ ‏اغْسِلْ ذَكَرَكَ ثُمَّ تَوَضَّأْ ثُمَّ ارْقُدْ ‏","","",""],[5241,5241,"","আমরা একটা আবেগ নিয়ে কথা বলেছি, যা আমরা প্রভুর ঋণের কথা শুনেছি... ...ঈশ্বরের পুত্র আছে, ঈশ্বরের কাছে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏بِلَالٌ ‏ ‏أَوْ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5242,5242,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমরা প্রভুর পুত্র নিয়ে এসেছি... ...যে ঈশ্বরের পুত্র ঈশ্বরের কাছে প্রার্থনা করেছে, তার মূল্য ছেড়ে দিতে বা তার প্রবেশ করতে। আমি তাকে সেলাই করে দিলাম.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرَةِ ‏ ‏أَوْ النَّخْلِ ‏ ‏حَتَّى يَبْدُوَ صَلَاحُهُ ‏ ‏فَقِيلَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا صَلَاحُهُ قَالَ ‏ ‏تَذْهَبُ ‏ ‏عَاهَتُهُ ‏","","",""],[5243,5243,"","আমরা আবেগ নিয়ে কথা বলেছি যে, আমরা ঈশ্বরের পুত্র দ্বারা সৃষ্ট একটি পুত্র যার নাম হয়েছে, তিনি আমার জন্য কথা বলেছেন। ঈশ্বর এটা উদ্ধার করতে বলেছেন এবং তিনি যে সিদ্ধান্ত নিয়েছেন, তিনি কি না। তিনি কি চান, আপনি তা বেছে নিয়েছেন। আমরা কি তাকে বেছে নিয়েছি?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ ابْتَاعَ طَعَامًا فَلَا يَبِيعُهُ حَتَّى يَقْبِضَهُ ‏","","",""],[5244,5244,"","আমরা ঈশ্বরের ঋণের শেষ শিকার হয়েছি... ...তার ছেলে ছিল শেষ, তাই ঈশ্বর আমাদের জন্য প্রার্থনা করতো, আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَا وَرَجُلٌ آخَرُ فَجَاءَ رَجُلٌ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏اسْتَأْخِرَا فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانُوا ثَلَاثَةً فَلَا يَتَنَاجَى اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[5245,5245,"","আমরা আমাদের দিনের হৃদয়ে যে আবেগ নিয়ে কথা বলেছি তা আমাদের কাছে অনেক বদলে দিয়েছে। যদি তিনি তার পায়ের তলায় বসে থাকেন, তিনি মনে করেন আপনি আমার প্রাণ ও প্রাণ হারিয়ে ফেলেছেন যদি তুমি এটা হারিয়ে ফেলতে তাহলে আমি তাকে ক্ষমা করে দেব শপথের জন্য, সে ঈশ্বরের বার্তাবাহকের কাছে প্রার্থনা করে...","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ أَمَرَ رَجُلًا إِذَا أَخَذَ مَضْجَعَهُ قَالَ ‏ ‏اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا لَكَ مَمَاتُهَا وَمَحْيَاهَا إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا اللَّهُمَّ أَسْأَلُكَ ‏ ‏الْعَافِيَةَ ‏ ‏فَقَالَ لَهُ رَجُلٌ سَمِعْتَ هَذَا مِنْ ‏ ‏عُمَرَ ‏ ‏فَقَالَ مِنْ خَيْرٍ مِنْ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5246,5246,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা ঈশ্বরের দোহাইে হৃদয়ের সাথে লড়াই করেছে। আল্লাহ আছে, তিনি বলবেন, রাতটা আমার মত যদি তুমি সকালে ভয় পাও, তাহলে তুমি চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَاسْجُدْ سَجْدَةً وَرَكْعَتَيْنِ قَبْلَ الصُّبْحِ ‏","","",""],[5247,5247,"","আমরা একটা আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমাদের এক কাপুরুষের ছেলে দ্বারা বহন করতে বাধ্য করেছে। আমার মেয়ে একটা দেওয়াল, যে বলল যে ভবিষ্যদ্বাণীটি তার জন্য দেয়া হয়েছে। আমি বলেছিলাম যে আমি এমন কিছু করতে পারব না যা করার অনুমতি আমার নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ بْنَ جُبَيْرٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏طَلَّقْتُ امْرَأَتِي وَهِيَ حَائِضٌ قَالَ فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ ‏ ‏لِيُرَاجِعْهَا فَإِذَا طَهُرَتْ فَإِنْ شَاءَ فَلْيُطَلِّقْهَا ‏ ‏قَالَ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَفَتَحْتَسِبُ بِهَا قَالَ ‏ ‏مَا يَمْنَعُهُ نَعَمْ أَرَأَيْتَ إِنْ عَجَزَ وَاسْتَحْمَقَ ‏","","",""],[5248,5248,"","আমরা বাবার বিচার নিয়ে খুবই আবেগী কথা বলেছি। সে বলবে, কুকুরকে নিয়ে যারা কুকুর নিয়ে নিয়েছে, কুকুর বা শিকারী নয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا إِلَّا كَلْبَ زَرْعٍ أَوْ غَنَمٍ أَوْ صَيْدٍ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[5249,5249,"","আমরা একটা স্বপ্নের কথা বলেছিলাম, কিভাবে সে আমাকে চাবি দিয়ে সাহায্য করতে চেষ্টা করছে। সূর্যাস্ত, একটা ছেলে, দুই বার আনন্দের সাথে এসেছে। যারা ঈশ্বরের কাছে প্রার্থনা করেছিল তারা তাঁর কাছে প্রার্থনা করেছিল এবং এই জায়গাটিকে এই অবস্থায় রেখে গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏بِجَمْعٍ ‏ ‏فَأَقَامَ الصَّلَاةَ فَصَلَّى الْمَغْرِبَ ثَلَاثًا وَسَلَّمَ وَصَلَّى الْعَتَمَةَ رَكْعَتَيْنِ وَحَدَّثَ ‏ ‏سَعِيدٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏صَلَّاهَا فِي هَذَا الْمَكَانِ فَصَنَعَ مِثْلَ ذَا ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ مِثْلَ هَذَا فِي هَذَا الْمَكَانِ ‏","","",""],[5250,5250,"","আমরা এমন একটা ছেলের বিষয়ে কথা বলেছিলাম, যিনি ঈশ্বরের কাছে পাঠিয়েছিলেন, তাকে তা দিতে হয়েছিল । পণ্ডিতরা বলেন, প্রভু এবং মাইনরের লোকেরা মিনস্টারকে বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ قَالَ اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا وَالْمُقَصِّرِينَ يَا رَسُولَ اللَّهِ قَالَ اللَّهُمَّ ارْحَمْ الْمُحَلِّقِينَ قَالُوا يَا رَسُولَ اللَّهِ وَالْمُقَصِّرِينَ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[5251,5251,"","আমরা আমার বাবার কথা বলেছিলাম যে, ঈশ্বরের সন্তান হওয়ার জন্য তোমার বাবা ঘোড়া হাতে নিয়ে এসেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ تَلْبِيَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[5252,5252,"","আমি যা ভেবেছিলাম তার চেয়ে বেশি ঘোড়ায় চড়ে আমার বাবার সঙ্গে কথা বলেছিলাম । আমরা তার সাথে দেখা করেছি স্যারের সাথে প্রার্থনা করেছি যে তিনি আমাদের জীবনের কামনা আমাদের দিয়েছিলেন না। তিনি বলেছিলেন, তোমার রাগ প্রকাশ করে বলতে আপনি রাগে ফেটে পড়তে পারবেন না। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏قَالَ ‏ ‏ذَكَرْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّى بِالْعُمْرَةِ وَالْحَجِّ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَرْحَمُ اللَّهُ ‏ ‏أَنَسًا ‏ ‏وَهِلَ ‏ ‏أَنَسٌ ‏ ‏وَهَلْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا حُجَّاجًا فَلَمَّا قَدِمْنَا أَمَرَنَا أَنْ نَجْعَلَهَا عُمْرَةً إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ ‏ ‏أَنَسًا ‏ ‏بِذَلِكَ فَغَضِبَ ‏ ‏وَقَالَ ‏ ‏لَا تَعُدُّونَا إِلَّا صِبْيَانًا ‏","","",""],[5253,5253,"","আমরা ঈশ্বরের দোহাই দিয়ে ঈশ্বরের কাছে যা ঘটেছে, তার জন্য আমরা তাদের সাহায্য করতে কথা বলেছি, ভালোবাসার জন্য তাকে আত্মসমর্পণ করতে হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏","","",""],[5254,5254,"","আমি আমার মায়ের সাথে কথা বলেছি ঈশ্বর নিষেধ করা সম্পর্কে কথা বলতে। একজন শান্তিপূর্ণ মহিলার সুপারিশ করার মত কিছু আছে, বাবা, সেটা সে নয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ لَهُ شَيْءٌ ‏ ‏يُوصِي فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلَّا وَوَصِيَّتُهُ عِنْدَهُ مَكْتُوبَةٌ ‏","","",""],[5255,5255,"","আমরা শুধু আমার মাকে সাহায্য করেছি... ...তার ভাইয়ের একটা ছেলে আছে বলে যে আমার কাছে তার ছেলের টাকা নিয়ে খেলা করছে আর সে হঠাৎ করেই ভয় পেয়েছে। গান থেকে কিছু একটা, আর তুমি আমার ছেলের কথা উল্লেখ করেছ... ...তার কাছে প্রার্থনা করে সবাইকে বাঁচিয়েছ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَخْبَرَهُمْ ‏ ‏أَنَّ جَارِيَةً كَانَتْ ‏ ‏تَرْعَى لِآلِ ‏ ‏كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏غَنَمًا لَهُمْ وَأَنَّهَا خَافَتْ عَلَى شَاةٍ مِنْ الْغَنَمِ أَنْ تَمُوتَ فَأَخَذَتْ حَجَرًا فَذَبَحَتْهَا بِهِ وَأَنَّ ذَلِكَ ذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُمْ بِأَكْلِهَا ‏","","",""],[5256,5256,"","আমরা একজন দাসের সাথে কথা বলেছি যে কিনা ঈশ্বরের কাছে এক ভালো ছেলের কথা বলেছে, যে কিনা ঈশ্বরের অনুগ্রহ লাভ করেছে, তার কাছে কিছু আছে সুপারিশ করার আর জোর দেওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ مُسْلِمٍ يَبِيتُ لَيْلَتَيْنِ وَلَهُ شَيْءٌ يُوصِي فِيهِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[5257,5257,"","আমরা একটি হাত দিয়ে কথা বলেছি, ঈশ্বরের কাছে আমাদের প্রিয় ছেলের কথা বলছি, সে কখনো খাবে না যদি আমি তাকে বিশ্বাস করি বা তার চাচা কখনো তার মাংস পান করতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ بِشِمَالِهِ وَلَا يَشْرَبْ بِشِمَالِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[5258,5258,"","আমরা সবার সেরা লোকদের কথা বলেছি যারা আমাদের কথা বলেছে যে আমি ঈশ্বরের পুত্র। ঈশ্বর বলতে হবে, প্রভু, আমি আমার দাস। তিনি কোন বক্তৃতা না বলেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏رَجُلٌ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي رَجُلٌ أُخْدَعُ فِي الْبَيْعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏مَنْ بَايَعْتَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5259,5259,"","আমরা একটা ছেলেকে ঈশ্বরকে খেলতে বলেছিলাম । তোমার কাছে, তারা রাতের কোয়ার্টারে গিয়েছে আমি তাদের সবার শেষ রাতে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏وَعُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَمُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏جَدَّ ‏ ‏بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏وَكَانَ فِي بَعْضِ حَدِيثِهِمَا إِلَى رُبُعِ اللَّيْلِ أَخَّرَهُمَا جَمِيعًا ‏","","",""],[5260,5260,"","আমি কিভাবে একটি ছেলেকে সাহায্য করতে সক্ষম হবে সে সম্পর্কে কথা বলেছি। শহরে খুন হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ السَّخْتِيَانِيِّ ‏ ‏وَأَيُّوبَ بْنِ مُوسَى ‏ ‏وَإِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[5261,5261,"","আমরা আমাদের সেরাটার কথা বলেছি ঈশ্বরের একজন সন্তান হবার জন্য। ঈশ্বর এটা করেছেন প্রভুর এই ভুলের পথে, তিনি বলেছেন, \"প্রভু, আমরা চলে এসেছি।\" আমরা দুজন একসাথে বাস করি আর আমরা ঈশ্বরের কাছে চলে যাই.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ لِلْفَرَسِ ‏ ‏سَهْمَيْنِ ‏ ‏وَلِلرَّجُلِ ‏ ‏سَهْمًا ‏ ‏قَالَ وَبَعَثَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏نَحْوَ ‏ ‏تِهَامَةَ ‏ ‏فَأَصَبْنَا غَنِيمَةً فَبَلَغَ ‏ ‏سُهْمَانُنَا ‏ ‏اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنَفَّلَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[5262,5262,"","আমরা সবার সেরা লোকদের কথা বলেছি পৃথিবীর সবচেয়ে খারাপ দুই ছেলে সম্পর্কে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَطَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَحَرَّقَ ‏","","",""],[5263,5263,"","আমরা আমাদের সবচেয়ে ভালো লোকদের কথা বলেছি... ...আমার বাবার ছেলেকে একটা ছেলের জন্য ক্ষতিপূরণ দিতে যে ঈশ্বরকে বলতে বলেছে তার জন্য প্রার্থনা করতে, আর সে আমাদের তা রাখতে পারবে না তাকে না পাওয়া পর্যন্ত দাম দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتَبَايَعُوا الثَّمَرَةَ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهَا قَالَ وَمَا بُدُوُّ صَلَاحِهَا قَالَ تَذْهَبُ ‏ ‏عَاهَتُهَا ‏ ‏وَيَخْلُصُ طَيِّبُهَا ‏","","",""],[5264,5264,"","আমরা সবার সেরা লোকদের কথা বলেছি যারা আমাদের কথা বলেছে যে তারা এটা করতে যাচ্ছে কিনা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي ‏ ‏مَسْجِدَ قُبَاءَ ‏ ‏رَاكِبًا وَمَاشِيًا ‏","","",""],[5265,5265,"","আমি যা শুনেছি, সেই বিষয়ে আমরা কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَبِيعُوا الثَّمَرَةَ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[5266,5266,"","আমরা একটি কুকুর ছেলের কথা বলেছিলাম যে পাইলটটি শুনতে পেয়েছে যে সে পৃথিবীর সেরাটা শুনেছে। আমি একজন অতিথি যে কিনা ইতিমধ্যে আছে তা দেখার জন্য। ঈশ্বর আদেশ দিয়েছেন, ঈশ্বর তাঁর জীবন দিয়েছেন, ঈশ্বর তাকে ছেড়ে দিয়েছেন। তিনি আমাকে এটা দেবেন আর তিনি আর কখনো এটা দেখতে পাবেন না। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি মুক্তির জন্য প্রার্থনা করেন। আমি শুনেছি, সে চলে গেছে, আমি তাকে তোমার মতো করে শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَيْمَنَ ‏ ‏يَسْأَلُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَبُو الزُّبَيْرِ ‏ ‏يَسْمَعُ فَقَالَ كَيْفَ ‏ ‏تَرَى فِي رَجُلٍ طَلَّقَ امْرَأَتَهُ حَائِضًا فَقَالَ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَلَّقَ امْرَأَتَهُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُرَاجِعْهَا عَلَيَّ وَلَمْ يَرَهَا شَيْئًا وَقَالَ فَرَدَّهَا إِذَا طَهُرَتْ فَلْيُطَلِّقْ ‏ ‏أَوْ ‏ ‏يُمْسِكْ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَقَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمْ النِّسَاءَ فَطَلِّقُوهُنَّ ‏} ‏فِي قُبُلِ عِدَّتِهِنَّ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَسَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يَقْرَؤُهَا كَذَلِكَ ‏","","",""],[5267,5267,"","আমরা বাবার সাথে যা ঘটেছে তার কথা বলেছিলাম, সে বলেছিল আপনি একবার ঈশ্বরের কাছে প্রার্থনা করেছেন। ঈশ্বরের এটা করা উচিত এবং তিনি তা স্পর্শ করবেন না। ঈশ্বর জয়ী হয়েছেন এবং নিশ্চয়ই তাকে ধরে ফেলেছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ فَذَكَرَ ذَلِكَ إِلَى ‏ ‏عُمَرَ ‏ ‏فَانْطَلَقَ ‏ ‏عُمَرُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُمْسِكْهَا ‏ ‏حَتَّى تَحِيضَ غَيْرَ هَذِهِ الْحَيْضَةِ ثُمَّ تَطْهُرَ فَإِنْ بَدَا لَهُ أَنْ يُطَلِّقَهَا فَلْيُطَلِّقْهَا كَمَا أَمَرَهُ اللَّهُ عَزَّ وَجَلَّ وَإِنْ بَدَا لَهُ أَنْ يُمْسِكَهَا فَلْيُمْسِكْهَا ‏","","",""],[5268,5268,"","আমরা একটা বাচ্চা ছেলের কথা বলেছিলাম যে, ঈশ্বরের কথা বলতে গেলে, তাকে তিন দিনের মধ্যে তোমাদের সবাইকে আত্মসমর্পণ করতে হবে না, কিন্তু সে চলে গেছে। আমরা একটা কুত্তার বাচ্চাকে নিয়ে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ أُضْحِيَّتِهِ فَوْقَ ثَلَاثَةِ أَيَّامٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا غَابَتْ الشَّمْسُ مِنْ الْيَوْمِ الثَّالِثِ لَا يَأْكُلُ مِنْ لَحْمِ ‏ ‏هَدْيِهِ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏ذَلِكَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏فِي ‏ ‏الْهَدْيِ ‏ ‏وَالضَّحَايَا ‏","","",""],[5269,5269,"","আমরা একটি আবেগ নিয়ে কথা বলেছি, আমরা ঈশ্বরের কাছে ঋণী, ঈশ্বরের পুত্র, ঈশ্বরের পুত্র শুনেছি, ঈশ্বর যুদ্ধে আমাদের উদ্ধার করতে হবে, যদি আমরা কিছুই না করি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي ‏ ‏الْمُحْرِمِ ‏ ‏إِذَا لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ يَقْطَعُهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[5270,5270,"","আমরা এমন এক ঋণের কথা বলেছি, যা আমরা কথা বলেছি, যেমন, ঈশ্বরের পুত্র একটি ছেলেকে দেখতে গেলে, তার পথিকের কাছে প্রার্থনা করতে বলেছেন যে তিনি ঈশ্বরের কাছে প্রার্থনা করছেন এবং তিনি তা করবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُصَلِّي حَيْثُ تَوَجَّهَتْ بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏وَيَقُولُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[5271,5271,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের ঈশ্বরের ঋণ বহন করতে নিয়ে এসেছে। ঈশ্বরের একটি পুত্র আছে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং এই কুয়াশাতে যা তিনি দেখেছেন, তা আত্মসমর্পণ করেছেন। আমি এটা খাইনি বা না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَعْرَابِيًّا نَادَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏تَرَى فِي هَذَا الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[5272,5272,"","আমরা একটা আবেগ কথা বলেছি যা আমাদের কাছে প্রভুর ঋণ বহন করতে এনেছে, যা আমার ছেলে বলছে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমাদের বিশ্বাস করতে বাধ্য হয়েছে যখন সে আসবে যে ব ্ যক ্ তি উপুড় হয়ে পড়ে এবং সে-ই ব ্ যর ্ থ করার জন ্ যে উম ্ মুক ্ ত । যে ব ্ যক ্ তি উপুড় হয়ে পড়ে এবং বলে , এটাই তো একমাত্র মিথ ্ যাবাদী । অধিকাংশ মানুষের বিশ্বাস.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كُنَّا إِذَا ‏ ‏بَايَعْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ يُلَقِّنُنَا هُوَ فِيمَا اسْتَطَعْتَ ‏","","",""],[5273,5273,"","আমরা ঈশ্বরের কাছে একটি ধর্মের প্রতি আবেগশীল প্রচেষ্টা করেছি, আমি এক চাচার ছেলে যে কিনা ঈশ্বরের সাথে কথা বলেছিল, তার জন্য তার শান্তি সময় হবে এই বিস্ময়ের সুরকে অপমান করার। ( পড়ুন, গীতসংহিতা ৩৪: ৬.)","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏وَلِأَهْلِ ‏ ‏الشَّأْمِ ‏ ‏الْجُحْفَةَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَزَعَمُوا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏","","",""],[5274,5274,"","আমরা একটি ছেলেকে মৃত্যুর কথা বলেছি যে পাইলটের ছেলে এসেছিল বলে লোকজন এতই কষ্ট করে যে আমরা ঈশ্বরকে বলতে পারি আর তারা তা করবে না। যে লোকটাকে দেখতে না চায়, আমি তাকে ভয় পাই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏يَرْزُقُنَا التَّمْرَ قَالَ وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ ‏ ‏جَهْدٌ ‏ ‏فَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏وَنَحْنُ نَأْكُلُ فَيَقُولُ لَا ‏ ‏تُقَارِنُوا ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَرَى فِي ‏ ‏الِاسْتِئْذَانِ إِلَّا أَنَّ الْكَلِمَةَ مِنْ كَلَامِ ‏ ‏ابْنِ عُمَرَ ‏","","",""],[5275,5275,"","আমরা একটি ছেলে নিয়ে কথা বলেছি যে একটি ছেলে নিয়ে কথা বলেছি যে ঈশ্বর সম্পর্কে কথা বলতে পারে। তিনি তাকে বিগত দশ বছরে বা অন্যান্যতে স্পর্শ করেছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مُلْتَمِسًا فَلْيَلْتَمِسْهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏","","",""],[5276,5276,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা একটা ছেলেকে সিংহাসনের কাছে আনার রীতি তৈরি করেছি, ঈশ্বর বলে যে সে টেনে টেনে টেনে চলে গেছে, কিন্তু সে আমার দিকে তাকিয়ে নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ جَرَّ ثَوْبًا مِنْ ثِيَابِهِ ‏ ‏مَخِيلَةً ‏ ‏فَإِنَّ اللَّهَ لَا يَنْظُرُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5277,5277,"","আমরা একটি ছেলে কথা বলেছি যে একটি ছেলে তার সাথে কথা বলার জন্য সংগ্রাম করেছে. মানে সে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَبَلَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ هَكَذَا وَطَبَّقَ أَصَابِعَهُ مَرَّتَيْنِ وَكَسَرَ فِي الثَّالِثَةِ الْإِبْهَامَ ‏ ‏يَعْنِي قَوْلَهُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[5278,5278,"","আমরা আমার বাবার সাথে কথা বলেছি যে ঈশ্বরের কথা শুনেছে, যে একটা কুত্তার বাচ্চা, লর্ডের কাছে প্রার্থনা করছে যে আমাদের হত্যা করতে হবে যে তাকে হত্যা করেছে, তার প্রার্থনা কয়েকবার হয় আর লীগ বলছে রাতের সবচেয়ে খারাপটা হচ্ছে রাতের বেলায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوَتْرِ ‏ ‏قَالَ فَمَشَيْتُ أَنَا وَذَاكَ الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوَتْرُ ‏ ‏رَكْعَةٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ يَقُلْ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[5279,5279,"","আমরা নিশ্চিত যে আমরা সেই শাস্তি নিয়ে এসেছি... ...যে কিনা এক সাহসী কাপুরুষের সাহায্য করার চেষ্টা করছে, যে তার জীবন নিয়ে এসেছে। ডিনারের সময় সে বলেছে সে একটা ছেলে হয়েছে, আমরা ঈশ্বরের কাছে প্রার্থনা করেছি আর এই জায়গায় আত্মসমর্পণ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏أَقَامَ ‏ ‏بِجَمْعٍ ‏ ‏قَالَ وَأَحْسِبُهُ وَأَذَّنَ ‏ ‏فَصَلَّى الْمَغْرِبَ ثَلَاثًا ثُمَّ سَلَّمَ فَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ ثُمَّ قَالَ صَنَعَ بِنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فِي هَذَا الْمَكَانِ مِثْلَ هَذَا وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏صَنَعَ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ مِثْلَ هَذَا ‏","","",""],[5280,5280,"","আমরা ঈশ্বরের প্রতিজ্ঞা নিয়ে কথা বলেছি, যে কিনা মারা গেছে তার জন্য ভালো কিছু করার জন্য। আমি ঈশ্বরের কাছে প্রার্থনা করব, সে তোমাকে ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ قَدْ جَعَلَ عَلَيْهِ يَوْمًا ‏ ‏يَعْتَكِفُهُ ‏ ‏فِي الْجَاهِلِيَّةِ فَسَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ذَلِكَ ‏ ‏فَأَمَرَهُ أَنْ ‏ ‏يَعْتَكِفَ ‏","","",""],[5281,5281,"","আমরা এমন আবেগ নিয়ে কথা বলেছি, যা আমরা পৃথিবীকে দেখার আগে দিনের খবরে বলেছি, ঈশ্বর এমন একজন চাচাকে উদ্ধার করেছেন যে কিনা একজন চাচার কাছে বিক্রি করেছে, তার জন্য হয়তো তার জন্য অনেক ভালো কিছু হয়ে গেছে। মজা করার সাথে সাথে  BAR","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِلْبَائِعِ وَمَنْ بَاعَ عَبْدًا لَهُ مَالٌ فَمَالُهُ لِلْبَائِعِ إِلَّا أَنْ ‏ ‏يَشْتَرِطَ ‏ ‏الْمُبْتَاعُ ‏","","",""],[5282,5282,"","আমরা এই ঘটনার কথা বলেছি কিন্তু আমার ক্লাসের সবচেয়ে ভালো একটি ছেলে আমাদের জন্য হয়েছে, যে কিনা পাশ করেছে বলে যে ঈশ্বর কখনো এটা করতে পারেন নি। ভয় জীবন্ত ও ধূলির পঞ্চমাংশকে হত্যা করে এবং হৃদয়ের করুণতা ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْتُلُ ‏ ‏الْمُحْرِمُ ‏ ‏خَمْسًا الْحُدَيَّا وَالْغُرَابَ وَالْفَأْرَةَ وَالْعَقْرَبَ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏","","",""],[5283,5283,"","আমরা একটা নিশ্চিত বা এমন লোক সম্পর্কে কথা বলেছি যে আমাদের সাথে এমন কিছু হয়েছিল যার মৃত্যুর পর মারা গেছে। সে বলবে আমি তার কাছে ঋণী আর সব থেকে চমৎকার কিছু। আমরা জানি, আমরা তাকে খুঁজে পেয়েছি। একজন পুরুষ খুনি যে কিনা ভুল করে, আমি তার দোষ দিচ্ছি না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الشَّأْمِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنٌ ‏ ‏فَقَالَ النَّاسُ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[5284,5284,"","আমরা একটি নির্দিষ্ট বিরুপ কথা বলেছি যে আমরা একটি ছেলের জন্য যে কিনা ঈশ্বরের সাথে আচরণ করেছে. তিনি একটি শহরে একটি কাটা দিয়েছেন এবং তারপর তিনি তাদের সরিয়ে ফেলেন.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[5285,5285,"","আমরা কথা বলেছি, মাখন দিয়ে ঘুমের চেয়েও ভালো। আমরা সেখানে বসে ছিলাম পাথরের সন্ধান করার জন্য। আমি তাদের কাছে ঈশ্বরের কাছে প্রার্থনা করেছিলাম এবং তাকে কখনও বলি না যে, বাপ্তিস্মের জন্য ঈশ্বরের কাছে করা হয়েছে এবং এর মধ্যে দশ ভাগের এক ভাগ হল নিষিদ্ধ । আর জিজ্ঞেস করলো কে তার ঋণটা একা অনুভব করেছে, সে ঈশ্বরের বিরুদ্ধে আর আমি যার মানে... ...সঠিক পথে ধরা পড়ে আছে তার জীবনের চেয়ে নিরাপদ ভাবে... তারা তাদের বোমাগুলো রেখে গিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ بْنِ أَتَشٍ ‏ ‏أَخْبَرَنِي ‏ ‏النُّعْمَانُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ سَلْمَانَ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏صَنْعَاءَ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏بِمَكَّةَ ‏ ‏فَجَلَسْنَا إِلَى ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏إِلَى جَنْبِ جِدَارِ الْمَسْجِدِ فَلَمْ نَسْأَلْهُ وَلَمْ يُحَدِّثْنَا قَالَ ثُمَّ جَلَسْنَا إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَ مَجْلِسِكُمْ هَذَا فَلَمْ نَسْأَلْهُ وَلَمْ يُحَدِّثْنَا قَالَ فَقَالَ مَا بَالُكُمْ لَا تَتَكَلَّمُونَ وَلَا تَذْكُرُونَ اللَّهَ قُولُوا اللَّهُ أَكْبَرُ وَالْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَبِحَمْدِهِ بِوَاحِدَةٍ عَشْرًا وَبِعَشْرٍ مِائَةً مَنْ زَادَ زَادَهُ اللَّهُ وَمَنْ سَكَتَ غَفَرَ لَهُ أَلَا أُخْبِرُكُمْ بِخَمْسٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى قَالَ ‏ ‏مَنْ ‏ ‏حَالَتْ ‏ ‏شَفَاعَتُهُ ‏ ‏دُونَ ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ فَهُوَ مُضَادُّ اللَّهِ فِي أَمْرِهِ وَمَنْ أَعَانَ عَلَى خُصُومَةٍ بِغَيْرِ حَقٍّ فَهُوَ مُسْتَظِلٌّ فِي سَخَطِ اللَّهِ حَتَّى يَتْرُكَ وَمَنْ ‏ ‏قَفَا ‏ ‏مُؤْمِنًا أَوْ مُؤْمِنَةً حَبَسَهُ اللَّهُ فِي ‏ ‏رَدْغَةِ الْخَبَالِ ‏ ‏عُصَارَةِ ‏ ‏أَهْلِ النَّارِ وَمَنْ مَاتَ وَعَلَيْهِ دَيْنٌ أُخِذَ لِصَاحِبِهِ مِنْ حَسَنَاتِهِ لَا دِينَارَ ثَمَّ وَلَا دِرْهَمَ وَرَكْعَتَا الْفَجْرِ حَافِظُوا عَلَيْهِمَا فَإِنَّهُمَا مِنْ الْفَضَائِلِ ‏","","",""],[5286,5286,"","আমরা একটা ছেলের দিকে তাকিয়েই বাপ্তাইজিত হয়েছি, সে ভুল করে আমাকে গুলি করেছে, আমার ছেলে একটা হাসপাতাল আর সে প্রভুর কাছে একটা জিনিস বিক্রি করছে। একটা মাছি তার সমাধান বিক্রি করে, তারপর মানুষ মারা যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْحَسَنِ بْنِ أَتَشٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يُرِيدُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى عَلَى ‏ ‏عُطَارِدٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَهُوَ يُقِيمُ ‏ ‏حُلَّةً ‏ ‏مِنْ حَرِيرٍ يَبِيعُهَا فَأَتَى ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ رَأَيْتُ ‏ ‏عُطَارِدًا ‏ ‏يَبِيعُ ‏ ‏حُلَّتَهُ ‏ ‏فَاشْتَرِيهَا تَلْبَسْهَا إِذَا أَتَاكَ وُفُودُ النَّاسِ فَقَالَ ‏ ‏إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ ‏","","",""],[5287,5287,"","আমরা কঠিন কিছু সালাদ খুঁজে বের করার চেষ্টা করেছি... ... যাতে আমরা এমন এক সময় শুনতে পাই যখন আমি শুনেছি এটা হয়ত ঈশ্বরের কাছে প্রার্থনা করে। কিছু একটা বের করেছি অথবা তার ঋণের কথা দেখলাম না। ঈশ্বরের প্রেমের দ্বারা, ঈশ্বরের প্রেমের দ্বারা, ঈশ্বরের দয়ায়, ঈশ্বরের করুণায়, ঈশ্বরের করুণা দ্বারা, গৌরব - দয়া দ্বারা, এই গৌরব সম্বন্ধে বলা যেতে পারে । ঈশ্বর তাকে পরাজিত করেছেন এবং প্রভুর মতো গ্রহণ করেছেন । সে বলেছে, আমি শুনেছি।","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ سَلَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُوقَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِذَا سَمِعَ مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا أَوْ شَهِدَ مَعَهُ مَشْهَدًا لَمْ ‏ ‏يُقَصِّرْ ‏ ‏دُونَهُ ‏ ‏أَوْ ‏ ‏يَعْدُوهُ ‏ ‏قَالَ فَبَيْنَمَا هُوَ جَالِسٌ ‏ ‏وَعُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏يَقُصُّ عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏إِذْ قَالَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ بَيْنَ الْغَنَمَيْنِ إِنْ أَقْبَلَتْ إِلَى هَذِهِ الْغَنَمِ نَطَحَتْهَا وَإِنْ أَقْبَلَتْ إِلَى هَذِهِ نَطَحَتْهَا فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَيْسَ هَكَذَا فَغَضِبَ ‏ ‏عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏وَفِي الْمَجْلِسِ ‏ ‏عَبْدُ اللَّهِ بْنُ صَفْوَانَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كَيْفَ قَالَ رَحِمَكَ اللَّهُ فَقَالَ قَالَ ‏ ‏مَثَلُ الْمُنَافِقِ مَثَلُ الشَّاةِ بَيْنَ ‏ ‏الرَّبِيضَيْنِ ‏ ‏إِنْ أَقْبَلَتْ إِلَى ذَا ‏ ‏الرَّبِيضِ ‏ ‏نَطَحَتْهَا وَإِنْ أَقْبَلَتْ إِلَى ذَا ‏ ‏الرَّبِيضِ ‏ ‏نَطَحَتْهَا فَقَالَ لَهُ رَحِمَكَ اللَّهُ هُمَا وَاحِدٌ قَالَ كَذَا سَمِعْتُ ‏","","",""],[5288,5288,"","আমরা একটি ছেলে নাম বহন একটি ছেলে একটি ছেলে কথা কথা কথা কথা কথা বলা হয়েছে যে যে শুনতে পেয়েছে যে তিনি হবেন সেই ছেলে যে তার নাম শুনেছে লর্ড, আমি বাড়িতে পৌঁছে যাবো... ...আর আমি একটা ছেলের কথা শুনবো যে গুলের কাছে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْبَيْتِ ‏ ‏وَسَيَأْتِي مَنْ يَنْهَاكُمْ عَنْهُ فَتَسْمَعُونَ مِنْهُ قَالَ ‏ ‏يَعْنِي ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏جَالِسًا قَرِيبًا مِنْهُ ‏","","",""],[5289,5289,"","আমরা বধির বাবা-এর কথা বলেছি, আমরা আনন্দিত ছিলাম যে আমরা ঈশ্বরের দ্বিতীয় ঋণের কথা বলেছি। সে বলেছিল সে তার জন্য প্রার্থনা করবে এবং সে তার পর মার জন্য হাল ছেড়ে দেবে এবং সে ভুলে যাবে। সেরাটা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَهُوَ الرُّقْعَةُ فِي الرَّأْسِ ‏","","",""],[5290,5290,"","আমরা সেই বধিরদের কথা বলেছি, যে আমাদের সাথে কথা বলেছে, কিন্তু আমরা দুজন গোপন কথা বলেছি যে একটা ছেলের মুক্তি পেয়েছে। ভুল, আর নদী বিজয়ীরা রাতের জন্য প্রার্থনা করবে রাতের জন্য আর রাতের জন্য প্রার্থনা করবে রাতের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ الْأَهْوَازِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْمَغْرِبِ ‏ ‏وِتْرُ ‏ ‏صَلَاةِ النَّهَارِ فَأَوْتِرُوا صَلَاةَ اللَّيْلِ وَصَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى ‏ ‏وَالْوَتْرُ ‏ ‏رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ ‏","","",""],[5291,5291,"","আমরা কয়েকটা ঘোড়া নিয়ে কথা বলেছি, আমরা একটা ছেলের ঋণের ব্যাপারে কথা বলেছি যে কিনা একটা দেবীর জন্য বরাদ্দ করা হয়েছে। সে তার কাজ শেষ করেছে। মাথা.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَفْصٍ ‏ ‏حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْقَزَعِ ‏ ‏فِي الرَّأْسِ ‏","","",""],[5292,5292,"","আমরা রাজার কথা বলেছিলাম যে তিনি একটা ছেলেকে হত্যা করতে যাচ্ছেন । ( গীতসংহিতা ৫৫: ২২) কিন্তু, যিহোবা তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর প্রভু ঈশ্বরের কাছে প্রার্থনা করেছেন এবং বলবেন যে, তাঁর কাছে তাঁর হাত রয়েছে । মরতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ مُطِيعٍ ‏ ‏فَقَالَ مَرْحَبًا ‏ ‏بِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏ضَعُوا لَهُ وِسَادَةً فَقَالَ إِنَّمَا جِئْتُكَ لِأُحَدِّثَكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏نَزَعَ ‏ ‏يَدًا مَنْ طَاعَةِ اللَّهِ فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ لَا حُجَّةَ لَهُ وَمَنْ مَاتَ وَهُوَ مَفَارِقٌ لِلْجَمَاعَةِ فَإِنَّهُ يَمُوتُ مِيتَةً جَاهِلِيَّةً ‏","","",""],[5293,5293,"","আমরা একটি মহান মনের সঙ্গে কথা বলেছি, যিনি কথা বলেছেন যাজক দ্বারা আমাদের জীবিত থাকতে বলেছেন। আমরা বলেছিলাম তলোয়ারম্যান আমাকে যেতে বলেছেন। আমি বলেছিলাম অন্ত্যেষ্টিক্রিয়ার সময় আমরা বলেছিলাম আমরা একে অপরের সাথে দেখা করতে। আমি বলেছিলাম, আমরা যে অন্ত্যেষ্টিক্রিয়ার সময় আমরা এটা করেছি এবং এর মধ্যে দেখা করতে পারি। আমরা বলেছিলাম, আমরা যদি বলি, আমরা সবাই একসাথে থাকতে পারি। আমরা যদি বলেছি, আমরা এটা করি, আমরা তো আমাদের সাথে যোগ দিতে পারি। আমরা যদি আগে কখনও ভুলবো না, তাহলে আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা যদি বলি, আমরা শুধু একটা ছোট ছোট ছোট দলনে ভাগ করি, তাহলে আমরা এটাকে একসাথেই করতাম। কিন্তু আমরা শুধু একটা ছোট ছোট দল হিসেবে দেখি। কিন্তু আমরা যদি একসাথে থাকতাম, তাহলে আমরা এটাকে একসাথেই করি। আমরা শুধু একটা ছোটা হই। কিন্তু আমরা যদি বলি, আমরা শুধু একটা করে ফেলি, তাহলে আমরা শুধু একটা ছোটা হই। আর আমরা শুধু একটা করে ফেলি। আমি জানি না তারা ধরা পড়বে নাকি তারা যাবে। আমি তাদেরকে দুই জায়গায় ফোন করবো এবং তারপর বরফ তুলে নেব। আইরিস।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ قَيْسٍ الْمَأْرِبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ شَرَاحِيلَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُلْنَا مَا صَلَاةُ الْمُسَافِرِ فَقَالَ ‏ ‏رَكْعَتَيْنِ رَكْعَتَيْنِ إِلَّا صَلَاةَ الْمَغْرِبِ ثَلَاثًا قُلْتُ أَرَأَيْتَ إِنْ كُنَّا ‏ ‏بِذِي الْمَجَازِ ‏ ‏قَالَ وَمَا ‏ ‏ذُو الْمَجَازِ ‏ ‏قُلْتُ مَكَانًا نَجْتَمِعُ فِيهِ وَنَبِيعُ فِيهِ وَنَمْكُثُ عِشْرِينَ لَيْلَةً أَوْ خَمْسَ عَشْرَةَ لَيْلَةً قَالَ يَا أَيُّهَا الرَّجُلُ كُنْتُ ‏ ‏بِأَذْرَبِيجَانَ ‏ ‏لَا أَدْرِي قَالَ أَرْبَعَةَ أَشْهُرٍ أَوْ شَهْرَيْنِ ‏ ‏فَرَأَيْتُهُمْ يُصَلُّونَهَا رَكْعَتَيْنِ رَكْعَتَيْنِ وَرَأَيْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصْبَ ‏ ‏عَيْنِي يُصَلِّيهِمَا رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ ‏ ‏نَزَعَ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏حَتَّى فَرَغَ مِنْ الْآيَةِ ‏","","",""],[5294,5294,"","আমরা আমাদের সময়ের মহানতার দ্বারা বাপ্তাইজিত হয়েছি... ...আমার বাবার শপথের মাধ্যমে... ...সে হয়তো পৃথিবীর রাজা দ্বারা নিহত হতে পারে. আর সে নিজেকে আত্মসমর্পণ করবে... ...তার প্রভুর রীতি আছে, আমাকে জিজ্ঞেস করতে হবে যে এটা কে বলবে যে, আমি তাকে তোমার কাছে বলবো, না হয় তোমাকে বলবো, আর সে তার লোকদের প্রধান হিসেবে দেখবে অফিসার আমি ভেবেছিলাম সে এটা দেখেছে, \"দ্যা ম্যাজিক মেকার\"","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏سالِمًا ‏ ‏يَقُولُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُهُ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏مِمَّا ‏ ‏يَلِي ‏ ‏الْمَقَامَ ‏ ‏رَجُلٌ آدَمُ ‏ ‏سَبْطُ ‏ ‏الرَّأْسِ وَاضِعًا يَدَهُ عَلَى رَجُلَيْنِ ‏ ‏يَسْكُبُ ‏ ‏رَأْسُهُ ‏ ‏أَوْ يَقْطُرُ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَوْ ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏لَا أَدْرِي أَيَّ ذَلِكَ قَالَ ‏ ‏ثُمَّ رَأَيْتُ وَرَاءَهُ رَجُلًا أَحْمَرَ ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ أَعْوَرَ عَيْنِ الْيُمْنَى أَشْبَهُ مَنْ رَأَيْتُ مِنْهُ ‏ ‏ابْنُ قَطَنٍ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏","","",""],[5295,5295,"","তিনি তার জন্য প্রার্থনা করেছিলেন এবং বলেছিলেন যে, আমি ভুল করেছি । তারপর আমি ভুল দিয়ে চেষ্টা করেছি এবং বলে গেলাম, \"ওহ খোদা, যদি আমি বলি,\"","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أُتِيتُ وَأَنَا نَائِمٌ ‏ ‏بِقَدَحٍ ‏ ‏مِنْ لَبَنٍ فَشَرِبْتُ مِنْهُ حَتَّى جَعَلَ اللَّبَنُ يَخْرُجُ مِنْ أَظْفَارِي ثُمَّ نَاوَلْتُ ‏ ‏فَضْلِي ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ فَمَا ‏ ‏أَوَّلْتَهُ ‏ ‏قَالَ الْعِلْمُ ‏","","",""],[5296,5296,"","আমি একটা ছেলের ছেলেকে হত্যা করার চেষ্টা করছিলাম, তার ছেলেকে সাহায্য করার কথা বলেছিলাম । তার পাথরের মধ্যে, তার কাপড় নাও, মেরে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ الدَّرَاهِمَ وَأَبِيعُ بِالدَّرَاهِمِ وَآخُذُ الدَّنَانِيرَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَدْخُلَ حُجْرَتَهُ فَأَخَذْتُ بِثَوْبِهِ فَسَأَلْتُهُ فَقَالَ ‏ ‏إِذَا أَخَذْتَ وَاحِدًا مِنْهُمَا بِالْآخَرِ فَلَا يُفَارِقَنَّكَ وَبَيْنَكَ وَبَيْنَهُ بَيْعٌ ‏","","",""],[5297,5297,"","আমরা আমার বাবার জন্ম নেয়া সম্পর্কে কথা বলেছি, সে আমার ছেলের ছেলে হওয়ার জন্য প্রথম স্থানে পাবে তার প্রেমিকের জন্য প্রার্থনা থেকে। - জজ.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الظُّهْرِ فَرَأَى أَصْحَابُهُ أَنَّهُ قَرَأَ تَنْزِيلُ ‏ ‏السَّجْدَةِ ‏ ‏قَالَ ‏ ‏وَلَمْ أَسْمَعْهُ مِنْ ‏ ‏أَبِي مِجْلَزٍ ‏","","",""],[5298,5298,"","আমরা একটি ভাল ছেলের কথা বলেছি, আমি ঈশ্বরকে তার জন্য প্রার্থনা করতে দেখেছি এবং তিনি আমার কাছে সিংহাসনে পৌঁছানোর আগেই আসবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ وَوَجْهُهُ قِبَلَ الْمَشْرِقِ تَطَوُّعًا ‏","","",""],[5299,5299,"","আমরা আমাদের সংবাদের চেয়েও বেশি কথা বলেছি, আমার বাবা, বড় একটা ছেলের জন্য আমার বিয়ের জন্য লড়ার জন্য লড়াই করতে পেরে খুশি। থরফের শান্তি তাকে প্রান্তরে থাকার জন্য এবং শুয়ে থাকতে বাধ্য করেছে। তার সাথে, তাদের থেকে বাছাই করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَسْلَمَ ‏ ‏غَيْلَانُ بْنُ سَلَمَةَ الثَّقَفِيُّ ‏ ‏وَتَحْتَهُ عَشَرُ نِسْوَةٍ فِي الْجَاهِلِيَّةِ وَأَسْلَمْنَ مَعَهُ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَخْتَارَ مِنْهُنَّ أَرْبَعًا ‏","","",""],[5300,5300,"","আমরা হামাদকে বলতে চেষ্টা করেছি কিন্তু তোমার নাম জানতে চাই কাপুরুষের ছেলে কে সাহায্য করার জন্য। বাস্তবতা হলো, অন্যরা রং বিক্রি করে এই আগুনের রঙ বিক্রি করে দিয়েছে এবং বিক্রি করা হচ্ছে আগুন এবং বিক্রি করা হয়েছে। আল্লাহ তাকে উদ্ধার করতে বলেছেন এবং নীল রঙ থেকে তাকে খুঁজে বের করতে বলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيعُ الْإِبِلَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَبِيعُ بِالدَّنَانِيرِ وَآخُذُ مَكَانَهَا ‏ ‏الْوَرِقَ ‏ ‏وَأَبِيعُ ‏ ‏بِالْوَرِقِ ‏ ‏فَآخُذُ مَكَانَهَا الدَّنَانِيرَ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُهُ ‏ ‏خَارِجًا مِنْ بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ ‏ ‏لَا بَأْسَ بِهِ بِالْقِيمَةِ ‏","","",""],[5301,5301,"","আমার বাবার মায়ের স্বপ্নের কথা বলেছিলাম। একজন যাজকের ছেলে, যিনি ঈশ্বরের আদেশ শুনেছিলেন এবং তিনি বলতেন যে, তার অবশ্যই দরকার আছে। আমি তাদেরকে গ্রুপ বলে ডাকতে যাচ্ছি, না হয় ঈশ্বরকে বেছে নিতে হবে, তাদের হৃদয়ের জন্য নয়, এবং গেরিলাদের কাছ থেকে তোমাকে চিঠি লিখতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَابْنَ عَبَّاسٍ ‏ ‏حَدَّثَا أَنَّهُمَا ‏ ‏سَمِعَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى أَعْوَادِ الْمِنْبَرِ ‏ ‏لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ ‏ ‏وَدْعِهِمْ ‏ ‏الْجُمُعَاتِ أَوْ ‏ ‏لَيَخْتِمَنَّ ‏ ‏اللَّهُ عَلَى قُلُوبِهِمْ وَلَيُكْتَبُنَّ مِنْ الْغَافِلِينَ ‏","","",""],[5302,5302,"","আমরা একটা ছেলের কথা বলেছি যে পাশ করেছে। ভগবান আমাকে বিক্রি করে দিচ্ছে যাতে আমাকে হতাশ না হতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أُخْدَعُ فِي الْبَيْعِ قَالَ قُلْ لَا ‏ ‏خِلَابَةَ ‏","","",""],[5303,5303,"","আমরা আমাদের বাবাকে আরও বেশি বলেছি, যে আমার বাবার জন্য থাকে ভালোবাসায় ভিক্ষুকে দেখে। আমরা দেখেছি বরো আর আগুন তাদের দেখা যাচ্ছে। আমার মনে হয় আমরা ওর ভাইয়ের জন্য ক্লান্ত। শান্তি স্থাপন করুন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَنَابٍ يَحْيَى بْنُ أَبِي حَيَّةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُنَا وَمَا صَاحِبُ الدِّينَارِ وَالدِّرْهَمِ بِأَحَقَّ مِنْ أَخِيهِ الْمُسْلِمِ ثُمَّ لَقَدْ رَأَيْتُنَا بِأَخَرَةٍ الْآنَ وَلَلدِّينَارُ وَالدِّرْهَمُ أَحَبُّ إِلَى أَحَدِنَا مِنْ أَخِيهِ الْمُسْلِمِ ‏","","",""],[5304,5304,"","আমি শুনেছি ভগবানের কাছে প্রার্থনা করছে আর বলবে তুমি দরজার পেছনে লেগে আছো। তুমি ওদের কথা মানলে তোমার দৃষ্টির কথা মেনে চলবে, আর তারপর তুমি আর থাকবে না। বেঁচে গেলাম, তুমি দেবতাদের সন্তান হবে।","‏ ‏وَلَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَئِنْ أَنْتُمْ اتَّبَعْتُمْ ‏ ‏أَذْنَابَ ‏ ‏الْبَقَرِ وَتَبَايَعْتُمْ ‏ ‏بِالْعِينَةِ ‏ ‏وَتَرَكْتُمْ الْجِهَادَ فِي سَبِيلِ اللَّهِ لَيُلْزِمَنَّكُمْ اللَّهُ مَذَلَّةً فِي أَعْنَاقِكُمْ ثُمَّ لَا تُنْزَعُ مِنْكُمْ حَتَّى تَرْجِعُونَ إِلَى مَا كُنْتُمْ عَلَيْهِ وَتَتُوبُونَ إِلَى اللَّهِ ‏","","",""],[5305,5305,"","আমি ঈশ্বরের কাছে প্রার্থনা করব তিনি একটি লড়াই পরে একটি গাছ হতে হবে. এমনকি তিনি যদি তিনি না আমি তার দুঃখ জন্য না বাস হবে এবং আমি তাদের দেখাতে হবে এবং তাদের প্রদর্শন করা হবে না. আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার আত্মার অন ্ যিদিন তাদের আত্মার আত্মার আত্মার আত্মার আত্মার নামে আকর্ষণ করে । আত্মার আত্মার, বানর এবং শুকরের সঙ্গে জীবন মানে মৃত্যু এবং আমি এই বিষয়ে কথা বলছি না।","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَتَكُونَنَّ هِجْرَةٌ بَعْدَ هِجْرَةٍ إِلَى مُهَاجَرِ أَبِيكُمْ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى لَا يَبْقَى فِي الْأَرَضِينَ إِلَّا شِرَارُ أَهْلِهَا وَتَلْفِظُهُمْ أَرَضُوهُمْ وَتَقْذَرُهُمْ رُوحُ الرَّحْمَنِ عَزَّ وَجَلَّ وَتَحْشُرُهُمْ النَّارُ مَعَ الْقِرَدَةِ وَالْخَنَازِيرِ تَقِيلُ حَيْثُ يَقِيلُونَ وَتَبِيتُ حَيْثُ يَبِيتُونَ وَمَا سَقَطَ مِنْهُمْ فَلَهَا ‏","","",""],[5306,5306,"","আমি শুনেছি ভগবান তার জন্য প্রার্থনা করছে আর বলবে যে সে আমার মায়ের অনুগ্রহ থেকে বের হয়ে আসবে। তাদের মধ্যে থাকা কয়জন বলেছে যে সে এটা করবে কিনা, যদি তারা মনে করে, তারা এটা করে, তারা তাদের হত্যা করে, তারা সবাই হত্যা করে, সে তোমার প্রভুর অনুগ্রহ লাভ করে... ...আর দশ বার আত্মসমর্পণ করে...","‏ ‏وَلَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَخْرُجُ مِنْ أُمَّتِي قَوْمٌ يُسِيئُونَ الْأَعْمَالَ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏لَا أَعْلَمُ إِلَّا قَالَ يَحْقِرُ أَحَدَكُمْ عَمَلَهُ مِنْ عَمَلِهِمْ ‏ ‏يَقْتُلُونَ أَهْلَ الْإِسْلَامِ فَإِذَا خَرَجُوا فَاقْتُلُوهُمْ ثُمَّ إِذَا خَرَجُوا فَاقْتُلُوهُمْ ثُمَّ إِذَا خَرَجُوا فَاقْتُلُوهُمْ ‏ ‏فَطُوبَى ‏ ‏لِمَنْ قَتَلَهُمْ وَطُوبَى لِمَنْ قَتَلُوهُ كُلَّمَا طَلَعَ مِنْهُمْ قَرْنٌ قَطَعَهُ اللَّهُ عَزَّ وَجَلَّ فَرَدَّدَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِشْرِينَ مَرَّةً أَوْ أَكْثَرَ وَأَنَا أَسْمَعُ ‏","","",""],[5307,5307,"","আমরা যা বলেছি তা নিয়ে আমরা কথা বলেছি, ঈশ্বরের দোহাই, তাকে ছেড়ে দিতে হবে কেন সে তার জয়ের কথা শোনার জন্য অন্যদের কাছ থেকে ফিরে এসেছে কিন্তু তাকে তার বিরুদ্ধে যুদ্ধ করতে হবে। সে তোমাকে ভুলে যেতে বলেছে যে সে জিততে পেরেছে, সে তাদের কান্না শুনবে আর তারা আজ পর্যন্ত আর ফিরে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا رَجَعَ مِنْ ‏ ‏أُحُدٍ ‏ ‏سَمِعَ نِسَاءَ ‏ ‏الْأَنْصَارِ ‏ ‏يَبْكِينَ عَلَى أَزْوَاجِهِنَّ فَقَالَ لَكِنْ ‏ ‏حَمْزَةُ ‏ ‏لَا ‏ ‏بَوَاكِيَ ‏ ‏لَهُ فَبَلَغَ ذَلِكَ نِسَاءَ ‏ ‏الْأَنْصَارِ ‏ ‏فَجِئْنَ يَبْكِينَ عَلَى ‏ ‏حَمْزَةَ ‏ ‏قَالَ فَانْتَبَهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَسَمِعَهُنَّ وَهُنَّ يَبْكِينَ فَقَالَ ‏ ‏وَيْحَهُنَّ لَمْ يَزَلْنَ يَبْكِينَ بَعْدُ مُنْذُ اللَّيْلَةِ مُرُوهُنَّ فَلْيَرْجِعْنَ وَلَا يَبْكِينَ عَلَى هَالِكٍ بَعْدَ الْيَوْمِ ‏","","",""],[5308,5308,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে এক পিতার ভালোবাসা বহন করতে সাহায্য করেছে। এটা ঠিক যে তিনি ঈশ্বরের সাথে প্রেম করেছেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বলেছেন প্রভু আমাকে ক্ষমা করে দিয়ে বলছি, তুমিই সেই লোক যে কিনা... ...যার কারণে সে... সেই লোক যে কিনা নিহত হয়েছে, সেই রহস্যটি হচ্ছে... ... যতক্ষণ না সে তার হাতে ১০০ বার ফিরে আসে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ خَبَّابٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْفَضْلِ ‏ ‏أَوْ ‏ ‏ابْنُ الْفَضْلِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ قَاعِدًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ حَتَّى عَدَّ الْعَادُّ بِيَدِهِ مِائَةَ مَرَّةٍ ‏","","",""],[5309,5309,"","আমি আমার হত্যার চেষ্টা করে যাচ্ছি। তার জন্য প্রার্থনা করেছি এবং আত্মসমর্পণ করেছি এবং হয়ত এক ছেলের সেবা করেছি, যে কিনা কিনা প্রায় বছর আগে মারা গেছে, অথবা অনেক বছর আগে, ঈশ্বর এই কথা বলেছেন। ( যিশাইয় ১১: ১ - ৩) ঈশ্বর সকলকে উদ্ধার করবেন অথবা তারা তা করবে এবং তারা তা করবে । ভুল হওয়ার কোনো কারণ নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏تَوْبَةَ الْعَنْبَرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏الشَّعْبِيُّ ‏ ‏أَرَأَيْتَ حَدِيثَ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ قَاعَدْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَرِيبًا مِنْ سَنَتَيْنِ أَوْ سَنَةٍ وَنِصْفٍ فَلَمْ أَسْمَعْهُ رَوَى عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَيْرَ هَذَا ‏ ‏قَالَ ‏ ‏كَانَ نَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ ‏ ‏سَعْدٌ ‏ ‏فَذَهَبُوا يَأْكُلُونَ مِنْ لَحْمٍ فَنَادَتْهُمْ امْرَأَةٌ مِنْ بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَحْمُ ضَبٍّ فَأَمْسَكُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوا أَوْ اطْعَمُوا فَإِنَّهُ حَلَالٌ وَإِنَّهُ لَا بَأْسَ بِهِ ‏ ‏تَوْبَةُ ‏ ‏الَّذِي شَكَّ فِيهِ ‏ ‏وَلَكِنَّهُ لَيْسَ مِنْ طَعَامِي ‏","","",""],[5310,5310,"","আমরা একটি দাঙ্গার কথা ভেবে বাপ্তাইজিত হয়েছি, যেটা প্রভুর নামে শোনা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏سَمِعْتُ ‏ ‏حَكِيمًا الْحَذَّاءَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏سُئِلَ عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏رَكْعَتَيْنِ سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5311,5311,"","আমরা আমাদের সময়ানুবর্তী হয়ে বাপ্তিস্ম নিয়েছি একটা মেয়েকে মারার জন্য যে বাবার অগ্নিকান্ডের কথা শুনেছে... ...সে বলেছে যে সে তার আদালত এমন করেছে যে আমি কি বলছিনা তোমার মত করে, তুমি আর এমন কিছু দেখার জন্য বাধ্য নও যা আমি ঈশ্বরের অনুগ্রহ থেকে দেখেছি। ভগবানকে পাঠিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ طَلْحَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْخَصِيبِ ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا فَجَاءَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقَامَ رَجُلٌ مِنْ مَجْلِسِهِ لَهُ فَلَمْ يَجْلِسْ فِيهِ وَقَعَدَ فِي مَكَانٍ آخَرَ فَقَالَ الرَّجُلُ مَا كَانَ ‏ ‏عَلَيْكَ لَوْ قَعَدْتَ فَقَالَ لَمْ أَكُنْ أَقْعُدُ فِي مَقْعَدِكَ وَلَا مَقْعَدِ غَيْرِكَ بَعْدَ شَيْءٍ شَهِدْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ لَهُ رَجُلٌ مِنْ مَجْلِسِهِ فَذَهَبَ لِيَجْلِسَ فِيهِ ‏ ‏فَنَهَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5312,5312,"","আমরা এক প্রবল আবেগে বাপ্তাইজিত হয়েছি, বাবার হাতে আমরা খেলতে চেষ্টা করেছি। তারা নেকড়েদের জন্য অনুরোধ করে, যে কিনা তার জন্য প্রার্থনা করবে এবং ঈশ্বরের কাছে সাহায্য চাইবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ أَبِي نُعَيْمٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ شَيْءٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسِبُهُ سَأَلَهُ عَنْ الْمُحْرِمِ يَقْتُلُ الذُّبَابَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏يَسْأَلُونَ عَنْ الذُّبَابِ وَقَدْ قَتَلُوا ابْنَ بِنْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُمَا رَيْحَانَتِي مِنْ الدُّنْيَا ‏","","",""],[5313,5313,"","আমরা একটি প্রথা সম্পর্কে অনুপ্রনা তৈরী করা একটি অনুপ্রনাতী দ্বারা বাপ্তাইজিত হয়েছি। বাবার অর্থ হলো সঙ্গীতের অর্থ হচ্ছে সঙ্গীত। একটি ছেলের জন্য যে বলেছে, যখন কথা দিয়েছিল, ঈশ্বর তার জন্য প্রার্থনা করেছেন, তখন তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন। ঈশ্বর আমার সর্বোচ্চ চেষ্টা করেছেন, আর একবার, তিনি প্রার্থনা করেছেন, কিন্তু তিনি কখনো বলবেন না। আমরা প্রার্থনা করতে গিয়েছিলাম একটি দাঙ্গার কথা বলতে। আমি মনে করি না যে এটা হবে। আমার বাবার মইর জন্য খেলার স্থান আমার ছেলের মসজিদে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ يَعْنِي الْمُؤَذِّنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُسْلِمٍ أَبِي الْمُثَنَّى ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏إِنَّمَا ‏ ‏كَانَ الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَعْنِي مَرَّتَيْنِ مَرَّتَيْنِ ‏ ‏وَالْإِقَامَةُ مَرَّةً غَيْرَ أَنَّهُ يَقُولُ قَدْ قَامَتْ الصَّلَاةُ قَدْ قَامَتْ الصَّلَاةُ وَكُنَّا إِذَا سَمِعْنَا الْإِقَامَةَ تَوَضَّأْنَا ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَا أَحْفَظُ غَيْرَ هَذَا ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا جَعْفَرٍ ‏ ‏مُؤَذِّنَ ‏ ‏الْعُرْبَانِ ‏ ‏فِي مَسْجِدِ ‏ ‏بَنِي هِلَالٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ أَبِي الْمُثَنَّى ‏ ‏مُؤَذِّنِ ‏ ‏مَسْجِدِ الْجَامِعِ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ ‏","","",""],[5314,5314,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...একটা ছেলের বোঝা নিয়ে... ...যে কিনা দু'বার কথা শোনে। মানে, ঈশ্বরের ছেলে লর্ডের ছেলের সাথে সুখী হয়েছে। ঈশ্বর তার উপর আশীর্বাদ করেছেন, তারপর মহিলা তাকে তালাক দিয়ে দেয় তারপর তাকে ভিতরে ঢোকার আগে সে প্রাসাদে চলে যায়, এমনকি রাতে সে ভুলে যায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ رَزِينٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ تَكُونُ لَهُ الْمَرْأَةُ ثُمَّ يُطَلِّقُهَا ثُمَّ يَتَزَوَّجُهَا رَجُلٌ فَيُطَلِّقُهَا قَبْلَ أَنْ يَدْخُلَ بِهَا فَتَرْجِعُ إِلَى زَوْجِهَا الْأَوَّلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَذُوقَ ‏ ‏الْعُسَيْلَةَ ‏","","",""],[5315,5315,"","আমরা একটি দৈত্যের শাস্তির কথা বলেছি যা একটি দেবীর ছেলে, আল্লাহকে ছেড়ে দিতে হবে, ডাক্তার আর নকল। পৃথিবী আর তুমি অন্ধকারে আছো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَقَالَ ‏ ‏انْتَبِذُوا ‏ ‏فِي ‏ ‏الْأَسْقِيَةِ ‏","","",""],[5316,5316,"","আমরা একটি মনস্তত্ত্বের মাধ্যমে বাপ্তাইজিত হয়েছি, যে কারণে আমরা একটি মনস্তত্ত্বের মাধ্যমে যা পেয়েছি, তা হল আল্লাহ্‌র কাছ থেকে পাওয়া তাঁর জন্য প্রার্থনা করা এবং তার গর্ভের উপর উপনীত রাজ্য ইবেষন করা সেই দরজার বাইরে তার গরমের সময় থেকে বেরিয়ে আসা এবং চাঁদ আমাকে বলে যে, তার ছেলে ছেলে রয়েছে, যার একটা ছেলে আছে একটি ছেলে-সন ্ তান রয়েছে যা থেকে একটি ছেলে রয়েছে । একটি ছেলে রয়েছে যার জন ্ যে পুত ্ র সন ্ তান রয়েছে এবং যার জন ্ যে পুত ্ র রয়েছে কন ্ যা । একটি ছেলে রয়েছে যার জন ্ যে পুত ্ র সন ্ তান রয়েছে এবং যে তার জন ্ যে এক সন ্ তান নির ্ ধারিত রয়েছে । একটি ছেলে ছেলে-সন ্ তান তান পাবে যে তার ছেলে সন ্ তান নিয়ে গেছে । এমন একটা ছেলে আছে যার ছেলে আছে, যার ছেলে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏لَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا ثُمَّ صَلَّى عِنْدَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ ثُمَّ خَرَجَ إِلَى ‏ ‏الصَّفَا ‏ ‏مِنْ الْبَابِ الَّذِي يَخْرُجُ إِلَيْهِ فَطَافَ ‏ ‏بِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏قَالَ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏هُوَ سُنَّةٌ ‏","","",""],[5317,5317,"","আমরা একটি অদ্ভুত মুখের উপর যে miss হয়েছে একটি অদ্ভুত মুখর মধ্যে একটি moos আনা হয়েছে যে একটি miss প্রায় জীবন ছিল হাত অভিশাপ এবং তিনি বলেন যে আমি নিষিদ্ধ আছে ঈশ্বরকে উদ্ধার করতে। ( ২ করি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏يَكَادُ يَلْعَنُ ‏ ‏الْبَيْدَاءَ ‏ ‏وَيَقُولُ ‏ ‏أَحْرَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْمَسْجِدِ ‏","","",""],[5318,5318,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা একটা দাসের ছেলে নিয়ে একটা দাঙ্গা করেছি... ...যে কিনা তার আঙ্গুলের ছাপ শুনেছে, লর্ড তার কাছে প্রার্থনা করেছে আর ঈশ্বরের কাছে এটা সত্য এই ধরনের আচরণ এবং বিশ্বের আত্মার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنْ يَكُ مِنْ الشُّؤْمِ شَيْءٌ حَقٌّ فَفِي الْمَرْأَةِ وَالْفَرَسِ وَالدَّارِ ‏","","",""],[5319,5319,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা একটা দাসের ছেলে নিয়ে দাঙ্গা শুরু করেছি... ...যে কিনা তার আঙ্গুলের কথা শুনেছে। লর্ড প্রার্থনা করেছে তার জন্য। যে মায়া আমি তাকে অপমান করেছি, অথবা নির্দোষ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْحُمَّى مِنْ فَيْحِ جَهَنَّمَ فَأَطْفِئُوهَا بِالْمَاءِ ‏ ‏أَوْ بَرِّدُوهَا بِالْمَاءِ ‏","","",""],[5320,5320,"","আমরা একটি ছেলে সিংহাসন বহন করতে একটি প্রতিশ্রুতি দ্বারা একটি পুত্র সিংহাসন স্থাপন করা একটি আবেগ কথা কথা বলেছি, যে তার প্রতিজ্ঞার কথা শুনে আছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং বলেছেন, তাকে এখনও যেতে হবে। আমার কাছে নিয়ে এসো, প্রভু, আমি ভেবেছিলাম সে তার সাথে কথা বলবে অথবা বলবে যে আমি ভয় পাচ্ছি এটার উত্তরাধিকারী.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنْهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏مُحَمَّدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏ ‏أَوْ قَالَ خَشِيتُ أَنْ يُوَرِّثَهُ ‏","","",""],[5321,5321,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা একটা দাস সন্তানের জন্ম দিয়েছি... ...যে তার ভালবাসার কথা শুনেছে, সে কিভাবে বিমস্টোনের মধ্যে ছিল, তোমার কারো গলাও ভেঙ্গে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَيْحَكُمْ أَوْ قَالَ ‏ ‏وَيْلَكُمْ لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5322,5322,"","আমরা একটি আবেগ কথা বলেছি যা আমাদের কাছে একটি নির্দিষ্ট ছেলের সিংহাসন বহন করতে নিয়ে এসেছে যে কিনা তার হাতের কাছে সুরক্ষিত। একটি ছেলে তার কাছে প্রার্থনা করে। আমি সব কিছু মারা গেছে কিন্তু ঈশ্বরের শপথ, এটা একটা গরুর ড্রাই, আর এটা জানে কি করতে হবে, আর তুমি কি করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏مُحَمَّدًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُوتِيتُ مَفَاتِيحَ كُلِّ شَيْءٍ إِلَّا الْخَمْسَ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي ‏ ‏الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏","","",""],[5323,5323,"","আমরা একটা আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যে আমাদের কাছে এসেছে... ...যে আমাকে দেখেছে, তার ছেলে... ...সে নাকি রাবার ফাঁদের ফাঁদ... ...সে একটা নির্দিষ্ট জীবন দিয়ে মুক্ত হতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏مَرَّ بِرَجُلٍ قَدْ ‏ ‏أَنَاخَ ‏ ‏مَطِيَّتَهُ ‏ ‏وَهُوَ يُرِيدُ أَنْ ‏ ‏يَنْحَرَهَا ‏ ‏فَقَالَ ‏ ‏قِيَامًا مُقَيَّدَةً سُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5324,5324,"","আমরা দুই বছর ধরে তার বাবার স্বপ্ন দেখে এসেছি, সে হাল ছেড়ে দিত যদি মানুষ জানতে পারত আমি এক রাত দৌড়ের কথা জানতাম।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ عَلِمَ النَّاسُ مَا فِي الْوَحْدَةِ مَا أَعْلَمُ مَا سَرَى رَاكِبٌ بِلَيْلٍ وَحْدَهُ ‏","","",""],[5325,5325,"","আমরা একটি পাইলট ছেলে করেছি যার মাখনের বোতল ভালোর সাথে দেওয়া হয়। ঈশ্বর এবং ঈশ্বরকে দেওয়া হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ طَارِقٍ أَبُو قُرَّةَ الزَّبِيدِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏زَبِيدٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْحُصَيْبِ ‏ ‏بِالْيَمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَكَانَ قَاصًّا لَهُمْ ‏ ‏عَنْ ‏ ‏مُوسَى يَعْنِي ابْنَ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّقَ نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَقَطَّعَ ‏","","",""],[5326,5326,"","আমরা একটি পুত্রবধূর চেয়ে বেশি কিছু বলেছি, ঈশ্বর তাকে জিজ্ঞাসা করেছেন এবং তিনি আত্মসমর্পণ করেছেন যে তিনি তার নিজের ভাগ্যের মুখ বলি দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَجْعَلُ فَصَّ خَاتَمِهِ مِمَّا يَلِي بَطْنَ كَفِّهِ ‏","","",""],[5327,5327,"","ঈশ্বর ঈশ্বর তাদের বলেন যে, সমস্ত জাতিকেই যেন অন্ধ ও প্রলুব্ধ করে এবং আমার মায়ের সঙ্গে ঘোরে, যিনি কোনো ভাগ্য না বলে । আমার আত্মা, তুমি তাদের দেখতে পাবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏غُفْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ أُمَّةٍ ‏ ‏مَجُوسٌ ‏ ‏ومَجُوسُ ‏ ‏أُمَّتِي الَّذِينَ يَقُولُونَ لَا ‏ ‏قَدَرَ ‏ ‏إِنْ مَرِضُوا فَلَا تَعُودُوهُمْ وَإِنْ مَاتُوا فَلَا تَشْهَدُوهُمْ ‏","","",""],[5328,5328,"","আমরা বাবার সাহায্য শুনতে চেয়েছিলাম কিন্তু যখন তাকে গুলি করা হয়েছিল তখন আমরা তাকে খুঁজে পেয়েছি, আমি তার ইচ্ছার কথা জিজ্ঞেস করছি এবং সে যদি তোমাদের একজনকে ফোন করে, সে কখনো ফোন করবে না। সে গ্রামের সাথে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ ‏ ‏يُصَلِّي فَلَا يَدَعْ أَحَدًا يَمُرُّ بَيْنَ يَدَيْهِ فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّ مَعَهُ الْقَرِينَ ‏","","",""],[5329,5329,"","আমরা প্রভুর দয়ার ভয়ানক শপথ নিয়ে কথা বলেছি, কিন্তু ভুলের জন্য তাকে রাতের পর রাত পর্যন্ত তার ছেলেকে শেষ করতে বলেছি যতক্ষণ না তুমি শেষ করো, সে বলবে সূর্য একটা শহরের কবর নিয়ে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏مَاتَ فَأَرَادُوا أَنْ يُخْرِجُوهُ مِنْ اللَّيْلِ لِكَثْرَةِ الزِّحَامِ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنْ أَخَّرْتُمُوهُ إِلَى أَنْ تُصْبِحُوا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الشَّمْسَ تَطْلُعُ بِقَرْنِ شَيْطَانٍ ‏","","",""],[5330,5330,"","আমরা একজন ভালো বুড়ো বুড়োর কথা বলেছিলাম যে নিজের ছেলের সাথে পালিয়ে গেছে। তারা প্রত্যেক ঝুঁকি নিয়ে বের হয়ে গেছে। যে এটা করেছে সে কে পছন্দ করতে সাহায্য করবে। বেছে বেছে নেওয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِنْ مَنْزِلهِ فَمَرَرْنَا بِفِتْيَانٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏نَصَبُوا طَيْرًا يَرْمُونَهُ وَقَدْ جَعَلُوا لِصَاحِبِ الطَّيْرِ كُلَّ خَاطِئَةٍ مِنْ نَبْلِهِمْ قَالَ فَلَمَّا رَأَوْا ‏ ‏ابْنَ عُمَرَ ‏ ‏تَفَرَّقُوا فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏مَنْ فَعَلَ هَذَا لَعَنَ اللَّهُ مَنْ فَعَلَ هَذَا إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ مَنْ اتَّخَذَ شَيْئًا فِيهِ الرُّوحُ ‏ ‏غَرَضًا ‏","","",""],[5331,5331,"","আমার বাবার ছেলে কিভাবে আমাদের একটি ছেলের জন্য ভাল কাজ করতে বলে, যে আমার ঈশ্বর এবং তার পিতা ছিল, কনসুম এর কল্পনা।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَمِّرُ ‏ ‏الْخَيْلَ ‏","","",""],[5332,5332,"","আমরা বাবার ছেলের কথা বলেছি, একটি ছেলের জন্য ভালো করার জন্য যে ঈশ্বরকে পাঠিয়েছে, তার জন্য আমি আমার শেষ জীবন যাপন করছি, সে বলেছে সে তোমার মুখে নেই।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ إِنَّهَا حَائِضٌ قَالَ إِنَّهَا لَيْسَتْ فِي كَفِّكِ ‏","","",""],[5333,5333,"","আমরা একটা পাহাড় নিয়ে প্রার্থনা করেছি, আমরা একটা পাহাড় নিয়ে এসেছি, ঈশ্বরের কাছে একটি ছেলে খুঁজে পাওয়ার আগেই আমি একটি ছেলে খুঁজে পেয়েছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে এই নামে ডাকা হবে না। আমরা যা বলেছিলাম, তা দেখে আমরা তাকে দেখতে পেতাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يُصَلِّي فِي السَّفَرِ إِلَّا رَكْعَتَيْنِ غَيْرَ أَنَّهُ كَانَ ‏ ‏يَتَهَجَّدُ ‏ ‏مِنْ اللَّيْلِ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏فَقُلْتُ ‏ ‏لِسَالِمٍ ‏ ‏كَانَا ‏ ‏يُوتِرَانِ ‏ ‏قَالَ نَعَمْ ‏","","",""],[5334,5334,"","আমরা আমার বাবার ছেলের জন্য খেলতে গিয়ে উত্তেজিত হয়েছি। আমরা হ্রদে চড়তে চাই এবং তারপর ঈশ্বরকে এটা করতে বলি। ফেসার বলেছে তুমি করো না, না হয় তোমরা সেই লোক যারা জানে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَفَرَرْنَا فَأَرَدْنَا أَنْ نَرْكَبَ الْبَحْرَ ثُمَّ أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَا يَا رَسُولَ اللَّهِ نَحْنُ ‏ ‏الْفَرَّارُونَ ‏ ‏فَقَالَ ‏ ‏لَا بَلْ أَنْتُمْ ‏ ‏أَوْ أَنْتُمْ ‏ ‏الْعَكَّارُونَ ‏","","",""],[5335,5335,"","আমরা একটি আবেগ কথা বলেছি যে আমরা ঈশ্বরের ছেলের জন্য কিছু দৃষ্টি দিয়েছি যখন তিনি তার ছেলের সাথে আছেন। ঈশ্বর তাকে নিজের পরিচয় দিতে বলেছেন এবং তিনি যখন ভালো আছেন, তখন তিনি ভালো নন। প্রভু-এর ব্যবহৃত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏النَّذْرِ ‏ ‏وَقَالَ إِنَّهُ لَا يَأْتِي بِخَيْرٍ وَإِنَّمَا يُسْتَخْرَجُ بِهِ مِنْ الْبَخِيلِ ‏","","",""],[5336,5336,"","আমরা আবেগ দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা একটি শিশুর প্রতি ভালোবাসা প্রতিশ্রুতির অঙ্গীকারের একটি রীতি তৈরি করেছি. আমি খারাপ সময় কাটানোর পর, তিনি ঈশ্বরের কাছে শপথ করে বলেছিলেন যে, তিনি তা করবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقُمْتُ وَتَرَكْتُ ‏ ‏رَجُلًا ‏ ‏عِنْدَهُ مِنْ ‏ ‏كِنْدَةَ ‏ ‏فَأَتَيْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ فَجَاءَ ‏ ‏الْكِنْدِيُّ ‏ ‏فَزِعًا فَقَالَ جَاءَ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَجُلٌ فَقَالَ أَحْلِفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَقَالَ لَا وَلَكِنْ احْلِفْ بِرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَإِنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ يَحْلِفُ بِأَبِيهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحْلِفْ بِأَبِيكَ ‏ ‏فَإِنَّهُ مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ أَشْرَكَ ‏","","",""],[5337,5337,"","তিনি বলেছিলেন যে, আমার বাবা একটা মশার গুলির ওপর গুলি করেছিলেন, যেটা তিনি বলেছিলেন যে, একটা বঁড়শি দূরের একটা বঁড়শি । ( খ) কেন যিশু তাঁর শিষ্যদের জন্য প্রার্থনা করেছিলেন?","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي قُرَّةَ مُوسَى بْنِ طَارِقٍ ‏ ‏قَالَ قَالَ ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا ‏ ‏صَدَرَ ‏ ‏مِنْ الْحَجِّ ‏ ‏أَوْ الْعُمْرَةِ ‏ ‏أَنَاخَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏وَأَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏حَدَّثَهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعَرِّسُ بِهَا حَتَّى يُصَلِّيَ صَلَاةَ الصُّبْحِ ‏","","",""],[5338,5338,"","তিনি আমাকে বলেছিলেন যে, তিনি আমাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছেন, যেন আমি তাঁকে ঈশ্বরের কাছে প্রেরণ করি ।","‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏وَأَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى فِي ‏ ‏مُعَرَّسِهِ ‏ ‏فَقِيلَ لَهُ إِنَّكَ فِي ‏ ‏بَطْحَاءَ ‏ ‏مُبَارَكَةٍ ‏","","",""],[5339,5339,"","সে বলেছিল, আমরা কথা বলেছি, ঈশ্বর তাকে উদ্ধার করেছেন এবং তিনি জিতে গেছেন। সবচেয়ে ছোট যে গোলাপগুলোর সম্মান পাওয়া গেছে তার চেহারা।","‏ ‏قَالَ ‏ ‏وَقَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏عِنْدَ ‏ ‏الْمَسْجِدِ الصَّغِيرِ الَّذِي دُونَ الْمَسْجِدِ الَّذِي يُشْرِفُ عَلَى ‏ ‏الرَّوْحَاءِ ‏","","",""],[5340,5340,"","তিনি বলেছিলেন, আল্লাহ হয়ত এটা করেছেন তার সাথে কথা বলার মাধ্যমে যে তিনি ঈশ্বরের কাছে প্রার্থনা করতেন। আগুনের জন্য মূল কাটা পানি হচ্ছে নরকের জন্য কাটা। রেবেল ডেবি, ওকে ফোন করার জন্য দুঃখিত, সে পা-টিয়ালিস্ট।","‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْزِلُ تَحْتَ ‏ ‏سَرْحَةِ ‏ ‏الرُّوَيْثَةِ ‏ ‏عَنْ يَمِينِ الطَّرِيقِ فِي مَكَانٍ ‏ ‏بَطْحٍ ‏ ‏سَهْلٍ حِينَ يُفْضِي مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏دُونَ بَرِيدِ ‏ ‏الرُّوَيْثَةِ ‏ ‏بِمِيلَيْنِ وَقَدْ انْكَسَرَ أَعْلَاهَا وَهِيَ قَائِمَةٌ عَلَى سَاقٍ ‏","","",""],[5341,5341,"","তিনি বলেছিলেন যে ঈশ্বর তাঁর বক্তব্য দিয়ে শেষ করেছেন যে তিনি ঈশ্বরের সর্বোচ্চ কাজ করেছেন। একটি নতুন প্যারেডের পিছনে আমরা খুব সামান্য কয়েক মাইলের বেশি আনন্দ পেয়েছি। আগুনের ডান দিকে আগুনের আগুনের মত ছিল। ( গীতসংহিতা ৩৭: ১১) এই সিঁড়িগুলোর মধ্যে কী রয়েছে?","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى مِنْ وَرَاءِ الْعَرْجِ وَأَنْتَ ذَاهِبٌ عَلَى رَأْسِ خَمْسَةِ أَمْيَالٍ مِنْ الْعَرْجِ فِي مَسْجِدٍ إِلَى هَضْبَةٍ عِنْدَ ذَلِكَ الْمَسْجِدِ قَبْرَانِ ‏ ‏أَوْ ثَلَاثَةٌ ‏ ‏عَلَى الْقُبُورِ رَضْمٌ مِنْ حِجَارَةٍ عَلَى يَمِينِ الطَّرِيقِ عِنْدَ ‏ ‏سَلَامَاتِ ‏ ‏الطَّرِيقِ بَيْنَ أُولَئِكَ ‏ ‏السَّلَامَاتِ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَرُوحُ مِنْ الْعَرْجِ بَعْدَ أَنْ تَمِيلَ الشَّمْسُ ‏ ‏بِالْهَاجِرَةِ ‏ ‏فَيُصَلِّي الظُّهْرَ فِي ذَلِكَ الْمَسْجِدِ ‏","","",""],[5342,5342,"","তিনি বললেন, আল্লাহ তাঁর বক্তব্য দিয়ে গেছেন। আমার বাবা এমন একজন কুমারী যে আপনার আত্মাতে ভ্রমণ করবে। আগুন আর আগ্রহের মেঘের কাছে।","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَزَلَ تَحْتَ ‏ ‏سَرْحَةٍ ‏ ‏وَقَالَ ‏ ‏غَيْرُ ‏ ‏أَبِي قُرَّةَ ‏ ‏سَرَحَاتٍ ‏ ‏عَنْ يَسَارِ الطَّرِيقِ فِي ‏ ‏مَسِيلٍ ‏ ‏دُونَ هَرْشَا ذَلِكَ ‏ ‏الْمَسِيلُ ‏ ‏لَاصِقٌ عَلَى هَرْشَا ‏ ‏وَقَالَ ‏ ‏غَيْرُهُ لَاصِقٌ ‏ ‏بِكَرَاعِ ‏ ‏هَرْشَا ‏ ‏بَيْنَهُ وَبَيْنَ الطَّرِيقِ قَرِيبٌ مِنْ ‏ ‏غَلْوَةِ ‏ ‏سَهْمٍ ‏","","",""],[5343,5343,"","তিনি বলেছিলেন যে, ঈশ্বর নিজে নিজে যে - কথাবার্তা বলতেন, তা নিয়ে তিনি ভালভাবেই তাঁর সঙ্গে কথা বলেছিলেন । এক রহস্য, যার মধ্যে ছিল নির্ভীক মুখ খুঁজে না পাওয়া।","‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْزِلُ ‏ ‏بِذِي طُوًى ‏ ‏يَبِيتُ بِهِ حَتَّى يُصَلِّيَ صَلَاةَ الصُّبْحِ حِينَ قَدِمَ إِلَى ‏ ‏مَكَّةَ ‏ ‏وَمُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏غَلِيظَةٍ لَيْسَ فِي الْمَسْجِدِ الَّذِي بُنِيَ ثَمَّ وَلَكِنْ أَسْفَلَ مِنْ ذَلِكَ عَلَى ‏ ‏أَكَمَةٍ ‏ ‏خَشِنَةٍ غَلِيظَةٍ ‏","","",""],[5344,5344,"","তিনি আমাকে বলেছিলেন যে, ঈশ্বর হয়তো তাঁর সবচেয়ে ভালো বিষয়গুলো দিয়ে বলেছিলেন । আমি তাকে শপথ করে বলতে চাই, লর্ডকে দশ বার বা এমনকি দশ বার বলা হয়। তার কাছে যে দুটি স্তর আছে তা হল পৃথিবীর সবচেয়ে অত্যাচারী।","‏ ‏قَالَ وَأَخْبَرَنِي أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبَلَ فُرْضَتَيْ الْجَبَلِ الطَّوِيلِ الَّذِي قِبَلَ ‏ ‏الْكَعْبَةِ ‏ ‏فَجَعَلَ الْمَسْجِدَ الَّذِي بُنِيَ يَمِينًا وَالْمَسْجِدُ بِطَرَفِ ‏ ‏الْأَكَمَةِ ‏ ‏وَمُصَلَّى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْفَلُ مِنْهُ عَلَى ‏ ‏الْأَكَمَةِ ‏ ‏السَّوْدَاءِ يَدَعُ مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏عَشْرَ أَذْرُعٍ أَوْ نَحْوَهَا ثُمَّ ‏ ‏يُصَلِّي مُسْتَقْبِلَ ‏ ‏الْفُرْضَتَيْنِ ‏ ‏مِنْ الْجَبَلِ الطَّوِيلِ الَّذِي بَيْنَهُ وَبَيْنَ ‏ ‏الْكَعْبَةِ ‏","","",""],[5345,5345,"","আমরা আমার বাবার কথা বলেছিলাম দুইজনের মৃত্যুর কথা। দুইবার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْمُثَنَّى ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏الْأَذَانُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثْنَى مَثْنَى وَالْإِقَامَةُ وَاحِدَةً غَيْرَ أَنَّ الْمُؤَذِّنَ كَانَ إِذَا قَالَ قَدْ قَامَتْ الصَّلَاةُ قَالَ قَدْ قَامَتْ الصَّلَاةُ مَرَّتَيْنِ ‏","","",""],[5346,5346,"","আমরা কথা বলেছিলাম যে, একটা ছেলের জন্য আপনি কত ভাল করছিলেন, যিনি তার জন্য এসেছিলেন এবং আমার ছেলেকে ছেড়ে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ ‏","","",""],[5347,5347,"","আমরা ঈশ্বরের পুত্র হওয়ার ব্যাপারে আমাদের স্বপ্নের কথা বলেছি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[5348,5348,"","আমরা কথা বলেছি আমাদের এমন একটা ছেলে খুঁজে বের করতে হবে যার থামার দরকার ছিল। এটাকে বল, একটা টুকরো টুকরো বা আমার বাবার ব্যাপারে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏نَهْشَلِ بْنِ مُجَمِّعٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏لُقْمَانَ الْحَكِيمَ ‏ ‏كَانَ يَقُولُ إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا اسْتُوْدِعَ شَيْئًا حَفِظَهُ ‏ ‏و قَالَ ‏ ‏مَرَّةً ‏ ‏نَهْشَلٌ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏","","",""],[5349,5349,"","আমরা আপনাদের তথ্য দাতার খবর নিয়ে কথা বলেছি। আমরা তাকে তোমার ছেলেকে খুন করতে বলেছিলাম। আমার পরিতৃপ্তি এমন একটা ছেলের দ্বারা ভেঙে গেছে যে বলে আমরা ঈশ্বরের কাছে কখনো তার কাছে যাই নি। আর আমাকে বলেছে এটা করতে, ঈশ্বর, সে যা রেখে গিয়েছে আমি তাকে ফোন করব.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنِي ‏ ‏نَهْشَلُ بْنُ مُجَمِّعٍ الضَّبِّيُّ ‏ ‏قَالَ ‏ ‏وَكَانَ مَرْضِيًّا ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏لُقْمَانَ الْحَكِيمَ ‏ ‏كَانَ يَقُولُ إِنَّ اللَّهَ إِذَا اسْتُوْدِعَ شَيْئًا حَفِظَهُ ‏","","",""],[5350,5350,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম... ...তার প্রভুর মৃত্যুর এক বছর পর... ...তার কাছে একটা মই আছে যেটা ভাল ধ্বংস হয়ে গেছে আর সঠিক তথ্য দিয়ে তৈরি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابًا ‏ ‏وَمُبِيرًا ‏","","",""],[5351,5351,"","আমরা একটা মশার কথা বলেছিলাম যে কিনা হয়তো তাকে ধ্বংস করতে চেয়েছিল, তার এই কাজের মাধ্যমে সে আমরা ঈশ্বরের প্রেম অর্জন করেছি। সে তার জন্য ঈশ্বরের প্রার্থনা পাঠ করে আর সে এটা দিয়ে দেবে। তার মনে হয় তিনি ধার্মিকদের অধিকার আছে আপনি বলা হয় আমরা সেরা. সে হারিয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَسَنُ بْنُ مُوسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَرَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الْآيَةَ وَهُوَ عَلَى الْمِنْبَرِ ‏ { ‏وَالسَّمَوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ ‏} ‏قَالَ يَقُولُ اللَّهُ أَنَا الْجَبَّارُ أَنَا الْمُتَكَبِّرُ أَنَا الْمَلِكُ أَنَا الْمُتَعَالِي يُمَجِّدُ نَفْسَهُ قَالَ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَدِّدُهَا حَتَّى رَجَفَ بِهِ الْمِنْبَرُ حَتَّى ظَنَنَّا أَنَّهُ ‏ ‏سَيَخِرُّ ‏ ‏بِهِ ‏","","",""],[5352,5352,"","আমরা যেভাবে বলেছিলাম, আমরা প্রভুকে বলেছিলাম যে আমরা এটা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ كَأَنَّ الْأَذَانَ فِي أُذُنَيْهِ ‏","","",""],[5353,5353,"","আমরা কথা বলেছিলাম কিভাবে তিনি একটি ছেলে হতে হবে. এবং তিনি তিনি ঈশ্বরের কথা তিনি তার জন্য প্রার্থনা করা এবং তিনি সুচতু সূর্য মত তিনি যে একটি পুত্র, এবং আপনি একটি পুত্র বলেন যে এবং আপনি মিথ্যা বলা হবে না. ঈশ্বরের কাছে প্রার্থনা করে তিনি ঈশ্বরের কাছে আত্মসমর্পণ করেছেন, তিনি ভণ্ডের মত একটি ভণ্ডের মত কাজ করেছেন, যেভাবে সেই ন্যাংটা মেয়ে গান গেয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ يَزْدَوَيْهِ ‏ ‏عَنْ ‏ ‏يَعْفُرَ بْنِ رُوذِيٍّ ‏ ‏سَمِعْتُ ‏ ‏عُبَيْدَ بْنَ عُمَيْرٍ ‏ ‏وَهُوَ يَقُصُّ ‏ ‏يَقُولُ ‏ ‏يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ ‏ ‏الرَّابِضَةِ ‏ ‏بَيْنَ ‏ ‏الْغَنَمِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَيْلَكُمْ لَا تَكْذِبُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ ‏ ‏الْعَائِرَةِ ‏ ‏بَيْنَ الْغَنَمَيْنِ ‏","","",""],[5354,5354,"","আমরা সবার সেরা জনতার কথা বলছি, যেখানে বলা হয়েছে, প্রভু আমাকে বলেছেন আমি একজন যাজক, ঈশ্বর তাকে রাতে উদ্ধার করতে হবে, তারপর তিনি আমাদের কাছে মসজিদে চলে যান এবং তারপর তিনি তার পরে তিনি আমাদের কাছে হেরে যান আমাদের ঘুম থেকে উঠে যেতে হবে, তারপর আমরা ঈশ্বরের কাছে অনুরোধ করব যেন কেউ তাকে দেখতে না পারে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شُغِلَ عَنْهَا لَيْلَةً فَأَخَّرَهَا حَتَّى رَقَدْنَا فِي الْمَسْجِدِ ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا ثُمَّ رَقَدْنَا ثُمَّ اسْتَيْقَظْنَا فَخَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ ‏ ‏لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ اللَّيْلَةَ يَنْتَظِرُ الصَّلَاةَ غَيْرُكُمْ ‏","","",""],[5355,5355,"","আমরা শপথ নিয়ে কথা বলেছি ঈশ্বরের নাম থেকে ভালো হওয়ার ব্যাপারে। একটি ছেলে যে ঈশ্বরকে প্রার্থনা করতে বলেছে, তার কাছে প্রার্থনা করেছে যে ভালো হবে। আমার বাবা তার অনুগত থাকার পর.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَبَرَّ ‏ ‏الْبِرِّ ‏ ‏صِلَةُ ‏ ‏الْمَرْءِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ ‏ ‏يُوَلِّيَ ‏","","",""],[5356,5356,"","আমরা আমার ছেলের বড় খবর পেয়েছি যে ঈশ্বরের দাস হিসেবে আমাকে কথা বলেছে, ঈশ্বর আদেশ দিয়েছেন আর আমি ঈশ্বরকে এই খেলার জন্য দেব সিংহাসনের বড় বড়, আমার রাতের জন্য একটি রাজ্য, যার থেকে আমি তার ক্ষমতা খরচ করতে হবে,","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ ‏ ‏لِلْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏اسْتَأْذَنَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبِيتَ ‏ ‏بِمَكَّةَ ‏ ‏لَيَالِيَ ‏ ‏مِنًى ‏ ‏مِنْ أَجْلِ ‏ ‏سِقَايَتِهِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[5357,5357,"","আমরা একটি মহান মন নিয়ে কথা বলেছি যে আমরা একটি গুরুতর গান করেছি যা আমার সাথে ঘটেছে। আমি তাকে বলেছি তার প্রার্থনা জানতে এবং তিনি বমির মাথায় তার মাথা তুলে দিতেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ رَأْسَهُ فِي حَجَّةِ الْوَدَاعِ ‏","","",""],[5358,5358,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি, যেমন আমরা একটা ছেলে যে ঈশ্বরের কাছে বড় হয়েছি, তার ব্যাপারে কি আমরা কথা বলেছি। কিছু লোক তার চুল নিয়ে স্বপ্ন দেখছে আর এর কিছু আছে। মুখ দিয়ে মুখ দিয়ে সব বলে দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى صَبِيًّا قَدْ حُلِقَ بَعْضُ شَعَرِهِ وَتُرِكَ بَعْضُهُ فَنَهَى عَنْ ذَلِكَ وَقَالَ ‏ ‏احْلِقُوا كُلَّهُ أَوْ اتْرُكُوا كُلَّهُ ‏","","",""],[5359,5359,"","ঈশ্বরের একজন শিক্ষক হওয়ার পর আমরা আমার শ্বশুরের সঙ্গে কথা বলেছিলাম, যিনি তার জন্য ভালবাসা দেখিয়েছিলেন । সুরক্ষা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَخِي الزُّهْرِيِّ عَبْدِ اللَّهِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ الْمَسْأَلَةُ بِأَحَدِكُمْ حَتَّى يَلْقَى اللَّهَ وَمَا فِي وَجْهِهِ ‏ ‏مُزْعَةُ ‏ ‏لَحْمٍ ‏","","",""],[5360,5360,"","আমরা জনতাকে কথা বলেছি যে বিয়ের ব্যাপারে আমি বলতে চাই, আমি তোমাকে বলতে চাই, ঈশ্বর হয়ত তার পতাকার মধ্যে দিয়ে এগিয়ে এসেছেন এবং তিনি তার পতাকা উদ্ধার করেছেন। তার প্রাণশক্তির জন্য তিনি আপনাকে বলেছিলেন এটা প্রায় একশ বছর স্থায়ী হবে, লর্ডের অনুগ্রহে, ঈশ্বর তাকে ধরে রেখেছেন এবং আপনার কাছে আত্মসমর্পণ করবেন যখন তারা শুধু এই মহিলার কথাই বলে। ঈশ্বর তাকে শিখিয়েছিলেন এবং সেই দিন তিনি আর রক্ষা পাবেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَأَبُو بَكْرِ بْنُ سُلَيْمَانَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ صَلَاةَ الْعِشَاءِ فِي آخِرِ حَيَاتِهِ فَلَمَّا سَلَّمَ قَامَ قَالَ أَرَأَيْتُمْ لَيْلَتَكُمْ هَذِهِ عَلَى رَأْسِ مِائَةِ سَنَةٍ مِنْهَا لَا ‏ ‏يَبْقَى مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَوَهِلَ ‏ ‏النَّاسُ فِي مَقَالَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ فِيمَا يَتَحَدَّثُونَ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ وَإِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبْقَى الْيَوْمَ مِمَّنْ هُوَ عَلَى ظَهْرِ الْأَرْضِ يُرِيدُ أَنْ يَنْخَرِمَ ذَلِكَ الْقَرْنُ ‏","","",""],[5361,5361,"","তিনি বলেছিলেন যে, দুজন ব্যক্তি ঈশ্বরকে এমন এক ব্যক্তি হয়ে ওঠে, যিনি রাতভর শেষ পর্যন্ত এসে ঈশ্বরের কাছে এসে টাকা জমাতে রাত পর্যন্ত এগিয়ে এসেছেন । সকাল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا حَسَدَ إِلَّا عَلَى اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُ مِنْهُ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ ‏ ‏وَآنَاءَ ‏ ‏النَّهَارِ ‏","","",""],[5362,5362,"","তিনি আপনাকে এমন একজন মই খুঁজে বের করতে পারেন, যার একজন ভাল শত্রু হিসেবে দেখা হয়, যে কোনো মানুষ তাকে ভ্রমণকারী হিসেবে খুঁজে পায় না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجِدُونَ النَّاسَ كَإِبِلٍ مِائَةٍ لَا يَجِدُ الرَّجُلُ فِيهَا ‏ ‏رَاحِلَةً ‏","","",""],[5363,5363,"","আমরা পৃথিবীর সেরাদের কথা বলছি, যে কিনা ঈশ্বরকে দেখে তার জীবনের বাকিটা ছেড়ে দিতে হবে। সে এই পোশাকটা অনেক খুশি এবং সুখী। এত জোরে মারা গেছে আমি মনে করি সে বলেছে ভগবানকে ক্ষেপে উঠতে সক্ষম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏ثَوْبًا أَبْيَضَ فَقَالَ أَجَدِيدٌ ثَوْبُكَ أَمْ غَسِيلٌ فَقَالَ فَلَا أَدْرِي مَا رَدَّ عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا ‏ ‏أَظُنُّهُ قَالَ وَيَرْزُقُكَ اللَّهُ ‏ ‏قُرَّةَ عَيْنٍ ‏ ‏فِي الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[5364,5364,"","আমার বাবা এমন একজন ছেলে ছিলেন, যিনি তার কাছে প্রার্থনা করেছিলেন এবং বলবেন যে, তিনি সঠিক ও সঠিক ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مَسْحَ الرُّكْنِ الْيَمَانِي وَالرُّكْنِ الْأَسْوَدِ ‏ ‏يَحُطُّ ‏ ‏الْخَطَايَا ‏ ‏حَطًّا ‏","","",""],[5365,5365,"","আমরা আমাদের সবচেয়ে ভালো একটা ছেলের জন্য যে তার কাছে এসেছিল তার সম্বন্ধে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَلِمُ الرُّكْنَ ‏ ‏الْيَمَانِيَ وَلَا يَسْتَلِمُ الْآخَرَيْنِ ‏","","",""],[5366,5366,"","আমরা আমাদের বড় ছেলে যে - ফুলটা পেয়েছিল, সেই সম্বন্ধে আমরা সবচেয়ে ভাল কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَلَقَ فِي حَجَّتِهِ ‏","","",""],[5367,5367,"","তিনি বলেছিলেন যে, তিনি সেটা পাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَنْزِلُونَ ‏ ‏بِالْأَبْطَحِ ‏","","",""],[5368,5368,"","আমি তার কোর্টে তার ভাইয়ের বিচার করব না । বসে পড়ো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُقِمْ أَحَدُكُمْ أَخَاهُ فَيَجْلِسَ فِي مَجْلِسِهِ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏فَكَانَ الرَّجُلُ يَقُومُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مِنْ مَجْلِسِهِ فَمَا يَجْلِسُ فِي مَجْلِسِهِ ‏","","",""],[5369,5369,"","আমরা সেই দিন সম্বন্ধে কথা বলেছিলাম যখন আমরা পর্দার কারণে মারা গিয়েছিলাম । ( যিশাইয় ৫৫: ১০) ঈশ্বরের কাছে সাহায্য চেয়ে প্রার্থনা করা, যা তিনি যা চান, সেটার জন্য তিনি যা করতে পারেন । ( যোহন ১৭: ৩) এই অপরাধী আমার কাছে কথা বলেছে কিন্তু ঈশ্বর তাঁর কাছে যা বলেছেন, তা তাঁর কাছে আর নেই । তার আদর্শ রেখে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِذَا بَلَغَ الرَّجُلُ الْمُسْلِمُ أَرْبَعِينَ سَنَةً آمَنَهُ اللَّهُ مِنْ أَنْوَاعِ الْبَلَايَا مِنْ الْجُنُونِ وَالْبَرَصِ ‏ ‏وَالْجُذَامِ ‏ ‏وَإِذَا بَلَغَ الْخَمْسِينَ لَيَّنَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ حِسَابَهُ وَإِذَا بَلَغَ السِّتِّينَ رَزَقَهُ اللَّهُ إِنَابَةً يُحِبُّهُ عَلَيْهَا وَإِذَا بَلَغَ السَّبْعِينَ أَحَبَّهُ اللَّهُ وَأَحَبَّهُ أَهْلُ السَّمَاءِ وَإِذَا بَلَغَ الثَّمَانِينَ تَقَبَّلَ اللَّهُ مِنْهُ حَسَنَاتِهِ وَمَحَا عَنْهُ سَيِّئَاتِهِ وَإِذَا بَلَغَ التِّسْعِينَ غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ وَسُمِّيَ أَسِيرَ اللَّهِ فِي الْأَرْضِ وَشُفِّعَ فِي أَهْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْعَامِرِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5370,5370,"","ঈশ্বর তা করতে পারেন আর আমি বন্যা পার হয়ে যেতে পেরে বা অন্যদেরকে বলা হয়েছিল যে, একদিন আপনার বন্ধু ও আপনার বন্ধু । ছেলে একটা জামা পরে আছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْتَرِي الذَّهَبَ بِالْفِضَّةِ أَوْ الْفِضَّةَ بِالذَّهَبِ قَالَ ‏ ‏إِذَا اشْتَرَيْتَ وَاحِدًا مِنْهُمَا بِالْآخَرِ فَلَا يُفَارِقْكَ صَاحِبُكَ وَبَيْنَكَ وَبَيْنَهُ ‏ ‏لَبْسٌ ‏","","",""],[5371,5371,"","আমরা একটা ছেলেকে হত্যা করতে বলেছিলাম যে ঈশ্বরকে মারতে বাধ্য হয়েছে। সে ঈশ্বরের কাছে প্রার্থনা করে তার বাবাকে ছেড়ে দিয়েছে। লোকেরা এমনকি যখন লোকেরা একটা টুইডো আঘাত করত, তখনও তা ভেঙে যায় ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّاسَ اجْتَمَعُوا فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَزَعَ ذَنُوبًا أَوْ ذَنُوبَيْنِ وَفِي نَزْعِهِ ضَعْفٌ وَاللَّهُ يَغْفِرُ لَهُ ثُمَّ قَامَ ‏ ‏ابْنُ الْخَطَّابِ ‏ ‏فَاسْتَحَالَتْ ‏ ‏غَرْبًا ‏ ‏فَمَا رَأَيْتُ عَبْقَرِيًّا مِنْ النَّاسِ ‏ ‏يَفْرِي ‏ ‏فَرِيَّهُ ‏ ‏حَتَّى ضَرَبَ النَّاسُ بِعَطَنٍ ‏","","",""],[5372,5372,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছি বলে বলা হয়েছিল আর যখন আমি তাঁর নাম ঘোষণা করে তাঁর নামে চলতে ক্লান্ত হয়ে পড়ি, তখন তিনি তা রক্ষা পাবেন । মহারাজ আমার সাথে কথা বলেছেন, তিনি তার সর্বোচ্চ চেষ্টা করেছেন। আর যদি আমার জন্য যুদ্ধ করা হতো... ... আর তিনি যা কথা দিয়েছিলেন সব মানুষকেই ভালোবাসার জন্য। ভাল, এটা আপনার পছন্দ থেকে। এটা আপনার পছন্দ। আমি যদি আমার সাথে লড়াই করি, আপনি যদি আপনি আপনার সিদ্ধান্তের মধ্যে থাকেন, আপনি আপনার পছন্দ অনুযায়ী আপনি কি করবেন? আপনি যদি আপনি আপনার কাজ করেন, আপনি আপনার জন্য একটি ভাল আপনার পছন্দ করেন, এবং আপনার পছন্দ, আপনার পছন্দ। এবং আপনার পছন্দ অনুযায়ী আপনি আপনার পছন্দ, আপনার পছন্দ, আপনার পছন্দ, এবং আপনার পছন্দ, আপনার পছন্দ, এবং আপনার পছন্দ, আপনার পছন্দ অনুযায়ী এটি আপনার জন্য। এবং আপনার পছন্দ। এবং আপনার জন্য এটা আপনার পছন্দ। এবং আপনার জন্য এটা আপনার জন্য। এবং আপনার পছন্দ। এবং আপনার জন্য আপনার জন্য এটা আপনার পছন্দ। এবং আপনার জন্য আপনার জন্য আপনার কাজ আপনার জন্য একটি সমাধান। এবং আপনার জন্য এটি আপনার জন্য। এবং আপনার জন্য আপনার জন্য আপনার জন্য এটি একটি ভাল। আপনার জন্য আপনার জন্য আপনার জন্য আপনার জন্য আপনার জন্য। এবং আপনার জন্য এটি একটি ভাল হবে। এবং আপনার জন্য ধন্যবাদ। এবং আপনার জন্য আপনার কাজ আপনার জন্য আপনার জন্য ধন্যবাদ। এবং আপনার জন্য ধন্যবাদ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَمَّرَ ‏ ‏أُسَامَةَ ‏ ‏بَلَغَهُ أَنَّ النَّاسَ يَعِيبُونَ ‏ ‏أُسَامَةَ ‏ ‏وَيَطْعَنُونَ فِي إِمَارَتِهِ فَقَامَ ‏ ‏كَمَا حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏فَقَالَ ‏ ‏إِنَّكُمْ تَعِيبُونَ ‏ ‏أُسَامَةَ ‏ ‏وَتَطْعَنُونَ فِي إِمَارَتِهِ وَقَدْ فَعَلْتُمْ ذَلِكَ فِي أَبِيهِ مِنْ قَبْلُ وَإِنْ كَانَ ‏ ‏لَخَلِيقًا ‏ ‏لِلْإِمَارَةِ وَإِنْ كَانَ لَأَحَبَّ النَّاسِ كُلِّهِمْ إِلَيَّ وَإِنَّ ابْنَهُ هَذَا بَعْدَهُ مِنْ أَحَبِّ النَّاسِ إِلَيَّ فَاسْتَوْصُوا بِهِ خَيْرًا فَإِنَّهُ مِنْ خِيَارِكُمْ ‏","","",""],[5373,5373,"","আমরা আমাকে খুন করার কথা বলেছিলাম। আমরা চেষ্টা করেছিলাম, আমি কীভাবে তা করতে পারি তা বলার জন্য। সে ঈশ্বরের কাছে প্রার্থনা করে আর সে তাকে যেতে দিত যে সে শুধু আমাকে মারতে পারত। তোমার কাছে কিছু একটা আছে, সে প্রভুর অনুগ্রহ পেয়েছে, সে সব কিছু খেয়ে ফেলবে, আর বলে আমি যা করছি তা কিছুই খাই না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ لَقِيَ ‏ ‏زَيْدَ بْنَ عَمْرِو بْنِ نُفَيْلٍ ‏ ‏بِأَسْفَلِ بَلْدَحَ وَذَلِكَ قَبْلَ أَنْ يَنْزِلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَحْيُ فَقَدَّمَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُفْرَةً ‏ ‏فِيهَا لَحْمٌ فَأَبَى أَنْ يَأْكُلَ مِنْهُ وَقَالَ ‏ ‏إِنِّي لَا آكُلُ مِمَّا تَذْبَحُونَ عَلَى ‏ ‏أَنْصَابِكُمْ ‏ ‏وَلَا آكُلُ مِمَّا لَمْ يُذْكَرْ اسْمُ اللَّهِ عَلَيْهِ ‏","","",""],[5374,5374,"","আমরা একটা পৃথিবীর কথা বলেছিলাম, কিন্তু ঈশ্বরের দয়ায় তার উপর ছিল... ...আর সে আমার কাছে দিয়েছে যে সে তার বংশধরদের মাঝে আছে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏أُتِيَ وَهُوَ فِي ‏ ‏الْمُعَرَّسِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏فَقِيلَ لَهُ إِنَّكَ ‏ ‏بِبَطْحَاءَ ‏ ‏مُبَارَكَةٍ ‏","","",""],[5375,5375,"","আমরা ঈশ্বরের সুসমাচারের বিষয়ে কথা বলেছি যখন তিনি বলেছিলেন তিনি কিছু করেছেন। ঈশ্বর তাঁর জন্য প্রার্থনা করেন এবং তিনি কিছু কবিতার ব্যবস্থা করেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏عَدَدْتُ ‏ ‏شَيْبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوًا مِنْ عِشْرِينَ شَعَرَةً ‏","","",""],[5376,5376,"","আমরা আদম সম্পর্কে কথা বলেছি যে, যে কিনা কাজের লাইন ভেঙ্গে ফেলতে পারবে, সে তার কথা বলেছে। আমি আর তার পিছনে নেই, আর তিন বার দূরে চলে যাব, আর সে যেখান থেকে এসেছিল, সেখানে ফিরে যাচ্ছে দুই বছর আর তৃষ্ণার তৃষ্ণা ফিরে আসছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ الْعَوْفِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْحَضَرِ وَالسَّفَرِ ‏ ‏فَصَلَّى الظُّهْرَ فِي الْحَضَرِ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ وَصَلَّى الْعَصْرَ أَرْبَعًا وَلَيْسَ بَعْدَهَا شَيْءٌ وَصَلَّى الْمَغْرِبَ ثَلَاثًا وَبَعْدَهَا رَكْعَتَيْنِ وَصَلَّى الْعِشَاءَ أَرْبَعًا وَصَلَّى فِي السَّفَرِ الظُّهْرَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ وَلَيْسَ بَعْدَهَا شَيْءٌ وَالْمَغْرِبَ ثَلَاثًا وَبَعْدَهَا رَكْعَتَيْنِ وَالْعِشَاءَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ ‏","","",""],[5377,5377,"","ঈশ্বরের দেওয়া সেই ব্যক্তির দেওয়াল সেই ব্যক্তির কাছে গিয়েছে, যিনি ঈশ্বরের কাছে প্রার্থনা করেছেন এবং প্রভু ও আমিই হবো । একজন দাস যে দুর্নীতি করে আর আমাকে বলে যে তুমি তাকে প্রতিদিন মার খেয়েছো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ الْحَجْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي خَادِمًا يُسِيءُ وَيَظْلِمُ أَفَأَضْرِبُهُ قَالَ ‏ ‏تَعْفُو عَنْهُ كُلَّ يَوْمٍ سَبْعِينَ مَرَّةً ‏","","",""],[5378,5378,"","আমরা আবার আমাকে বাঁচাতে কথা বলেছিলাম, যখন আমি মা সালিমকে জিজ্ঞাসা করলাম আর সে আমার মা তোমার টাকা ভুলে গেছে, ঈশ্বর তাকে জিজ্ঞেস করেছে আর আমাকে বলেছে যে সে আমাকে এটা বলতে বলেছে। ঘুমের মহিলা কখনো দেখে না যে লোকটি বলে যে তার প্রভুর ইচ্ছা আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُمَرَ يَعْنِي عَبْدَ الْجَبَّارِ الْأَيْلِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي سُمَيَّةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَأَلَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏وَهِيَ أُمُّ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏تَرَى الْمَرْأَةُ فِي الْمَنَامِ مَا يَرَى الرَّجُلُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَتْ الْمَرْأَةُ ذَلِكَ وَأَنْزَلَتْ فَلْتَغْتَسِلْ ‏","","",""],[5379,5379,"","আমরা তোমার পার্টনারের কথা বলেছিলাম বাবার সমৃদ্ধ ছেলে সম্পর্কে অন্ধের সাথে মোডে। ঈশ্বরের কাছে প্রার্থনা করলাম তার জন্য। আর সে যা করেছে, তা তাকে জিজ্ঞেস করব। সে যদি ঢাল নিতে চায়, সে ভয় পেয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي الصِّدِّيقِ النَّاجِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نِسَاءَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلْنَهُ عَنْ ‏ ‏الذَّيْلِ ‏ ‏فَقَالَ ‏ ‏اجْعَلْنَهُ شِبْرًا فَقُلْنَ إِنَّ شِبْرًا لَا يَسْتُرُ مِنْ عَوْرَةٍ فَقَالَ اجْعَلْنَهُ ذِرَاعًا فَكَانَتْ إِحْدَاهُنَّ إِذَا أَرَادَتْ أَنْ تَتَّخِذَ دِرْعًا أَرْخَتْ ذِرَاعًا فَجَعَلَتْهُ ذَيْلًا ‏","","",""],[5380,5380,"","আমরা ইশ্বরের সাথে কথা বলেছি আমরা আমাদের সাহায্য করার কথা বলেছিলাম, সে বলল যে তার ছেলে ঈশ্বরের ভালোর দ্বারা পাশ করেছে, সে বলে যে তার কাছে মিথ্যা বলেছে, সে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَمْزَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏أَنَّ شَاعِرًا قَالَ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَبِلَالُ ‏ ‏عَبْدُ اللَّهِ خَيْرُ ‏ ‏بِلَالِ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏كَذَبْتَ ذَاكَ ‏ ‏بِلَالُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5381,5381,"","আপনি ঈশ্বরের যোগ্য কোনো কিছুর ব্যাপারে বলেছিলেন, আপনার তা করার প্রয়োজন নেই । আমি ঈশ্বরের কথা শুনে শুনে রাখব, আমার মা ভাগ্যে শুয়ে আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِابْنِ عُمَرَ ‏ ‏صَدِيقٌ مِنْ أَهْلِ ‏ ‏الشَّأْمِ ‏ ‏يُكَاتِبُهُ فَكَتَبَ إِلَيْهِ مَرَّةً ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِنَّهُ بَلَغَنِي أَنَّكَ تَكَلَّمْتَ فِي شَيْءٍ مِنْ ‏ ‏الْقَدَرِ ‏ ‏فَإِيَّاكَ أَنْ تَكْتُبَ إِلَيَّ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ فِي أُمَّتِي أَقْوَامٌ يُكَذِّبُونَ بِالْقَدَرِ ‏","","",""],[5382,5382,"","আমি আমার বাবার কথা বলেছিলাম সে আমাকে কীভাবে খেলেছে সে কথা বলেছি। সে তার বাবার কাছে তার আশীর্বাদের জন্য প্রার্থনা করছিল আর তার কাছে প্রার্থনা করেছিল যে সে তা আর কখনো উদ্ধার করতে পারবে না। আমি তোমাকে বলতে চাই, আমি তোমাকে বলতে চাই, আল্লাহ তাদের হত্যা করবে না, তাদের থামাও।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏كَعْبُ بْنُ عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا النِّسَاءَ حُظُوظَهُنَّ مِنْ الْمَسَاجِدِ إِذَا اسْتَأْذَنَّكُمْ ‏ ‏فَقَالَ ‏ ‏بِلَالٌ ‏ ‏وَاللَّهِ لَنَمْنَعُهُنَّ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ لَنَمْنَعُهُنَّ ‏","","",""],[5383,5383,"","আমরা বাবাকে বললাম, আমাদের সবচেয়ে ভালোর কথা হলো, আমার সাথে কথা বলা। সে বলেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আগুনের শিখাকে এক কুড়াল মানুষ হিসেবে ঘোষণা করা হবে। ঈশ্বর এর পরেই নারানানের পিছু নিতে পারতাম, বাবা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّارُ عَدُوٌّ فَاحْذَرُوهَا ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَتَتَبَّعُ نِيرَانَ أَهْلِهِ فَيُطْفِئُهَا قَبْلَ أَنْ يَبِيتَ ‏","","",""],[5384,5384,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আপনাকে আমাদের কাছে প্রতিজ্ঞা করবেন না এবং একবার আমাদের সুরক্ষা করবেন । তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তাকে এখানে শয়তান থেকে খেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏شَامِنَا ‏ ‏ويَمَنِنَا ‏ ‏مَرَّتَيْنِ فَقَالَ رَجُلٌ وَفِي مَشْرِقِنَا يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ هُنَالِكَ يَطْلُعُ قَرْنُ الشَّيْطَانِ وَلَهَا تِسْعَةُ أَعْشَارِ الشَّرِّ ‏","","",""],[5385,5385,"","আমরা লেক বেটনের ব্যাপারে তর্ক করেছি... ...এটা একটা ছেলে যে তার কাছে প্রার্থনা করেছিল. বিখ্যাত আর একই সাথে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْحُرِّ بْنِ الصَّيَّاحِ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ الْخَمِيسَ ‏ ‏مِنْ أَوَّلِ الشَّهْرِ ‏ ‏وَالِاثْنَيْنِ الَّذِي يَلِيهِ ‏ ‏وَالِاثْنَيْنِ الَّذِي يَلِيهِ ‏","","",""],[5386,5386,"","আমরা তীর্থযাত্রীর সৃষ্টি করেছি এবং এক সময় আমার বাবার রাজধানীর জন্য ঈশ্বরের কাছে আমাদের একটি ছেলে হতো। সে বলল, সে ঈশ্বরের কাছে প্রার্থনা করুক, সে তার কাছে প্রার্থনা করুক এবং সে সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর সুন্দর এক দৃশ্য দিয়ে পৌঁছে দিয়েছে। মাতাল, বিখ্যাত এবং বিখ্যাত, এবং এমনকি সে কোন জায়গায় নেই।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُصْمٍ أَبِي عَلْوَانَ الْحَنَفِيِّ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي ‏ ‏ثَقِيفٍ ‏ ‏كَذَّابًا ‏ ‏وَمُبِيرًا ‏","","",""],[5387,5387,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন আর আপনি পাপের প্রায় ৯০ বছর ধরে বেঁচে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَدْخُلُوا عَلَى الْقَوْمِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ ‏","","",""],[5388,5388,"","আমরা যে যুক্তি নিয়ে কথা বলেছি, আমি কথা বলেছি একটা ছেলে সম্পর্কে যে কিনা হয়ত আমার সাথে কথা বলতে চেয়েছিল সে কি করেছে, আমি তাকে বলেছি ঈশ্বরের সবচেয়ে ভালো স্বার্থ পাঠাতে, সে যাবে। তার ভাইয়ের প্রয়োজন ছিল ঈশ্বরের সমবেদনা, তার প্রয়োজনের উপর, এবং যে দেবীর মুক্তি পায়, সে প্রভুর আনন্দে ফেটে পড়ে। মূল্যবোধকে দোষারোপ করা হবে... ...এবং শান্তি আত্মসমর্পণ করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ عَزَّ وَجَلَّ فِي حَاجَتِهِ وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ ‏ ‏كُرْبَةً ‏ ‏فَرَّجَ اللَّهُ عَزَّ وَجَلَّ عَنْهُ بِهَا ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏يَوْمِ الْقِيَامَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[5389,5389,"","আমার ছেলে সত্য হওয়া নিয়ে আমরা তর্ক করেছি। সে বলেছিল, সে তার গলা ভেঙ্গে ফেলবে না। সে মনে করে যে তিনিই সে-ই সেই তিনিই ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি, যিনি ছিলেন সেই ব্যক্তি । সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন একজন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏كَشَجَرَةٍ طَيِّبَةٍ ‏} ‏قَالَ هِيَ الَّتِي لَا تَنْفُضُ وَرَقَهَا ‏ ‏وَظَنَنْتُ أَنَّهَا النَّخْلَةُ ‏","","",""],[5390,5390,"","আমরা শপথ নিয়ে কথা বলেছি বাবা আর ওসতোর সাথে এটা করার জন্য তার শাস্তি সম্পর্কে। ঈশ্বরের ইচ্ছা তার কাছে প্রার্থনা করবে আর মাতালদের আমি অনেক কিছু জিজ্ঞাসা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ ‏","","",""],[5391,5391,"","আমাদের শপথের কথা বলেছিলাম আমরা আমাদের কাগজ চুরি করে নিয়ে যাব আর আমরা একজন ছেলের সম্পর্কে কথা বলেছি যে সে ছিল সেরা. পুরুষ এবং পৃথিবীর মানুষ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ثُوَيْرٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ ‏ ‏الْمُخَنَّثِينَ ‏ ‏مِنْ الرِّجَالِ وَالْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ ‏","","",""],[5392,5392,"","আমরা একটা ছেলের কাছ থেকে এক ছেলের জন্ম দেওয়ার কথা বলেছিলাম, যার ইচ্ছা ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ الْحَدَّادُ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْوَحْدَةِ أَنْ يَبِيتَ الرَّجُلُ وَحْدَهُ أَوْ يُسَافِرَ وَحْدَهُ ‏","","",""],[5393,5393,"","আমরা একটা মুক্ত নারীর নাম বলেছিলাম, যাকে ডাইনি বলে ডাকা হয় ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ حُرَيْثٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَ مِنْكُمْ مُلْتَمِسًا فَلْيَلْتَمِسْ فِي الْعَشْرِ الْأَوَاخِرِ وَإِنْ ضَعُفَ أَحَدُكُمْ أَوْ غُلِبَ فَلَا يُغْلَبْ عَلَى السَّبْعِ الْبَوَاقِي ‏","","",""],[5394,5394,"","আমরা একটা ছেলের কথা বলেছিলাম যে তাকে শান্তি দিবে, এটা তার সম্পর্ক হয়ে যাবে","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ تَلَقِّي السِّلَعِ حَتَّى يُهْبَطَ بِهَا الْأَسْوَاقُ ‏","","",""],[5395,5395,"","আমরা ঈশ্বরের ভালবাসার এক ছেলের কথা বলেছিলাম, আমি আমার চেহারার সাথে লড়াই করছিলাম আর তারা বলত যে তার ছেলে কখনো ছেলে হবে না, সে তার যথাসাধ্য করতে পারত। তারা বলেছিল যে, আমি ঈশ্বরের কাছে প্রার্থনা করেছি, যেন তিনি তা প্রদান করেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ أَعْرَابِيًّا مَرَّ عَلَيْهِ وَهُمْ فِي طَرِيقِ الْحَجِّ فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَلَسْتَ فُلَانَ بْنَ فُلَانٍ قَالَ بَلَى قَالَ فَانْطَلَقَ إِلَى حِمَارٍ كَانَ يَسْتَرِيحُ عَلَيْهِ إِذَا مَلَّ رَاحِلَتَهُ وَعِمَامَةٍ كَانَ يَشُدُّ بِهَا رَأْسَهُ فَدَفَعَهَا إِلَى الْأَعْرَابِيِّ فَلَمَّا انْطَلَقَ قَالَ لَهُ بَعْضُنَا انْطَلَقْتَ إِلَى حِمَارِكَ الَّذِي كُنْتَ تَسْتَرِيحُ عَلَيْهِ وَعِمَامَتِكَ الَّتِي كُنْتَ تَشُدُّ بِهَا رَأْسَكَ فَأَعْطَيْتَهُمَا هَذَا الْأَعْرَابِيَّ وَإِنَّمَا كَانَ هَذَا ‏ ‏يَرْضَى بِدِرْهَمٍ قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏أَبَرَّ ‏ ‏الْبِرِّ ‏ ‏صِلَةُ ‏ ‏الْمَرْءِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ أَنْ ‏ ‏يُوَلِّيَ ‏","","",""],[5396,5396,"","আমরা ঈশ্বরের কাছে প্রার্থনা করেছি, যিনি ঈশ্বরের দ্বারা পরিচালিত এক ছেলের জন্য, যিনি আল্লাহ্‌র অনুগ্রহে রাজি হয়েছেন। তিনি কোন আত্মসমর্পণ করেননি বা সিঁড়িতে সেলাই করেননি।","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏جَلَبَ ‏ ‏وَلَا ‏ ‏جَنَبَ ‏ ‏وَلَا ‏ ‏شِغَارَ ‏ ‏فِي الْإِسْلَامِ ‏","","",""],[5397,5397,"","আমরা আগেও বলেছি, ঈশ্বর একটা ছেলের জন্য একটা ভাল কাজ করেছেন যে আমার কাছে ভালবাসা দেখিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمَى ‏ ‏النَّقِيعَ ‏ ‏لِخَيْلِهِ ‏","","",""],[5398,5398,"","আমরা আগেও বলেছি, আল্লাহ একটা ছেলের জন্য একটা অনুগ্রহ নিয়ে এসেছে, যিনি ইতোমধ্যে এটা করেছেন। তিনি এই কাজ করেছেন এবং আগের জনকে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَبَّقَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْخَيْلِ وَأَعْطَى السَّابِقَ ‏","","",""],[5399,5399,"","আমরা আগে ঈশ্বরের কাছে কথা বলেছি যে ছেলে আমার প্রতি ভালবাসা দেখিয়েছে, পরিকল্পনাটার মধ্যে বসে আছে","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَجْلِسُ بَيْنَ الْخُطْبَتَيْنِ ‏","","",""],[5400,5400,"","ঈশ্বর তাকে এবং প্রভু ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং লোকেদের কাছে সমর্পণ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْتُولَةً ‏ ‏فَأَنْكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَتْلَ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""]];
